INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_001', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'การสังเคราะห์ด้วยแสงและพืชศาสตร์', 'ในกระบวนการสังเคราะห์ด้วยแสงของพืช สารตั้งต้นและผลผลิตหลักที่ได้คือข้อใด (ข้อที่ 1)', '["สารตั้งต้น: น้ำ + แก๊สคาร์บอนไดออกไซด์ / ผลผลิต: น้ำตาลกลูโคส + แก๊สออกซิเจน","สารตั้งต้น: แก๊สออกซิเจน + แป้ง / ผลผลิต: น้ำ + แก๊สคาร์บอนไดออกไซด์","สารตั้งต้น: น้ำตาลกลูโคส + น้ำ / ผลผลิต: คลอโรฟิลล์","สารตั้งต้น: ปุ๋ยไนโตรเจน / ผลผลิต: แก๊สคาร์บอนไดออกไซด์"]', 0, 'พืชใช้แสง น้ำ และ CO2 สังเคราะห์น้ำตาลกลูโคสและปล่อย O2 ออกมา', 'อย่าสับสนกับการหายใจของพืชที่ดูด O2 แล้วปล่อย CO2', 'สังเคราะห์แสง = ดูด CO2 ปล่อย O2', '["การสังเคราะห์ด้วยแสงและพืชศาสตร์","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_002', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'ระบบหมุนเวียนเลือดและหัวใจ', 'เส้นเลือดชนิดใดที่นำเลือดที่มีแก๊สออกซิเจนสูงจากปอดกลับเข้าสู่หัวใจห้องบนซ้าย (ข้อที่ 2)', '["พัลโมนารีเวน (Pulmonary Vein)","พัลโมนารีอาร์เตอรี (Pulmonary Artery)","เอออร์ตา (Aorta)","เวนาคาวา (Vena Cava)"]', 0, 'พัลโมนารีเวนเป็นเส้นเลือดเวนเส้นเดียวที่ลำเลียงเลือดแดงมีออกซิเจนสูงจากปอดสู่หัวใจ', 'ปกติเส้นเลือดเวนจะมีเลือดดำ แต่พัลโมนารีเวนเป็นข้อยกเว้น', 'จากปอดเข้าหัวใจ = พัลโมนารีเวน (เลือดแดง)', '["ระบบหมุนเวียนเลือดและหัวใจ","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_003', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ระบบย่อยอาหารและสารอาหาร', 'เอนไซม์ ''เปปซิน'' ในกระเพาะอาหารของมนุษย์ ทำหน้าที่ย่อยสารอาหารประเภทใดและทำงานได้ดีในสภาวะใด (ข้อที่ 3)', '["ย่อยโปรตีน ในสภาวะที่เป็นกรด (กรดไฮโดรคลอริก)","ย่อยไขมัน ในสภาวะที่เป็นเบส","ย่อยแป้ง ในสภาวะที่เป็นกลาง","ย่อยวิตามิน ในสภาวะที่เป็นกรด"]', 0, 'กระเพาะอาหารหลั่งกรดไฮโดรคลอริกเพื่อให้เอนไซม์เปปซินย่อยโปรตีนได้อย่างมีประสิทธิภาพ', 'เอนไซม์ในกระเพาะชอบกรด ส่วนในลำไส้เล็กชอบเบส', 'กระเพาะ = กรด + ย่อยโปรตีน', '["ระบบย่อยอาหารและสารอาหาร","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_004', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'โซ่อาหารและกฎ 10% พลังงาน', 'สิ่งมีชีวิตใดในระบบนิเวศที่มีบทบาทสำคัญในการเปลี่ยนอินทรียสารให้กลับคืนเป็นแร่ธาตุในดิน (ข้อที่ 4)', '["ผู้ย่อยสลายสารอินทรีย์ (Decomposers) เช่น เห็ด รา แบคทีเรีย","ผู้ผลิต (Producers) เช่น สาหร่ายและพืชสีเขียว","ผู้บริโภคซากสัตว์ (Scavengers) เช่น แร้ง","ผู้บริโภคลำดับสูงสุด"]', 0, 'เห็ด รา และแบคทีเรีย ย่อยสลายซากพืชซากสัตว์คืนธาตุอาหารลงสู่ดินและวัฏจักร', 'สัตว์กินซาก เช่น แร้ง เป็นผู้บริโภค ไม่ใช่ผู้ย่อยสลายอินทรียสารระดับโมเลกุล', 'ย่อยสลายคืนสู่ดิน = เห็ด รา แบคทีเรีย', '["โซ่อาหารและกฎ 10% พลังงาน","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_005', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'แรงพยุงและความหนาแน่น', 'วัตถุก้อนหนึ่งมีมวล 80 กรัม ปริมาตร 100 ลูกบาศก์เซนติเมตร เมื่อนำไปลอยในน้ำบริสุทธิ์จะมีสภาพเป็นอย่างไร (ข้อที่ 5)', '["ลอยน้ำ โดยมีปริมาตรจมน้ำ 80% และโผล่พ้นน้ำ 20%","จมลงสู่ก้นภาชนะทันที","ลอยน้ำ โดยมีปริมาตรจมน้ำ 20% และโผล่พ้นน้ำ 80%","ลอยปริ่มน้ำพอดี 100%"]', 0, 'ความหนาแน่นวัตถุ = 80/100 = 0.8 g/cm³ น้อยกว่าน้ำ (1.0) จึงลอย และมีสัดส่วนจม 80%', 'ความหนาแน่นวัตถุคือเปอร์เซ็นต์ส่วนที่จมน้ำ', 'ความหนาแน่น = สัดส่วนปริมาตรที่จมน้ำ', '["แรงพยุงและความหนาแน่น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_006', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'วงจรไฟฟ้าและกฎของโอห์ม', 'เมื่อนำหลอดไฟ 3 หลอดมาต่อกันแบบ ''ขนาน'' หากหลอดไฟดวงหนึ่งขาด หลอดไฟที่เหลือจะเป็นอย่างไร (ข้อที่ 6)', '["หลอดไฟที่เหลือยังคงสว่างตามปกติ","หลอดไฟที่เหลือจะดับทั้งหมดทันที","หลอดไฟที่เหลือจะสว่างลดลงครึ่งหนึ่ง","หลอดไฟที่เหลือจะระเบิด"]', 0, 'การต่อแบบขนาน กระแสไฟฟ้ามีทางเดินแยกกันเป็นอิสระ เมื่อหลอดหนึ่งขาด วงจรอื่นยังคงครบวงจร', 'ถ้าต่อแบบอนุกรม หลอดหนึ่งขาดจะดับทั้งหมด', 'ต่อขนาน = วงจรบ้าน = ดับ 1 ดวง ดวงอื่นยังสว่าง', '["วงจรไฟฟ้าและกฎของโอห์ม","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_007', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'แสง เลนส์ และการมองเห็น', 'ปรากฏการณ์ ''รุ้งกินน้ำ'' เกิดจากแสงอาทิตย์กระทบกับละอองน้ำในอากาศผ่านกระบวนการใดตามลำดับ (ข้อที่ 7)', '["การหักเห -> การสะท้อนกลับหมด -> การกระจายของแสง","การแทรกสอด -> การเลี้ยวเบน -> การดูดกลืน","การสะท้อนปกติ -> การรวมแสง","การแผ่รังสี -> การพาความร้อน"]', 0, 'แสงแดดส่องเข้าละอองน้ำ หักเหและกระจายแสงสี แล้วสะท้อนกลับหมดภายในหยดน้ำออกมาสู่สายตา', 'รุ้งกินน้ำจะเกิดทิศตรงข้ามกับดวงอาทิตย์เสมอ', 'รุ้งกินน้ำ = หักเห + กระจายแสง + สะท้อนกลับหมด', '["แสง เลนส์ และการมองเห็น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_008', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'การแยกสารและโครมาโทกราฟี', 'วิธีใดเหมาะสมที่สุดในการแยก ''เกลือแกง'' ออกจาก ''น้ำทะเล'' (ข้อที่ 8)', '["การระเหยแห้ง (Evaporation)","การกรองด้วยกระดาษกรอง","การใช้แม่เหล็กดูด","การสกัดด้วยตัวทำละลาย"]', 0, 'เกลือละลายเป็นเนื้อเดียวกับน้ำ ต้องใช้ความร้อนระเหยน้ำออกไปจนเหลือผลึกเกลือตกค้าง', 'การกรองไม่สามารถแยกสารที่ละลายเป็นเนื้อเดียวกันได้', 'น้ำเกลือระเหยแห้งได้ผลึกเกลือ', '["การแยกสารและโครมาโทกราฟี","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_009', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ชั้นบรรยากาศและสภาพอากาศ', 'แก๊สชนิดใดมีสัดส่วนปริมาณมากที่สุดในบรรยากาศของโลก (ข้อที่ 9)', '["แก๊สไนโตรเจน (ประมาณ 78%)","แก๊สออกซิเจน (ประมาณ 21%)","แก๊สคาร์บอนไดออกไซด์ (ประมาณ 0.04%)","แก๊สฮีเลียม"]', 0, 'อากาศมีแก๊สไนโตรเจนมากที่สุด 78% รองลงมาคือออกซิเจน 21% และอาร์กอน/คาร์บอนไดออกไซด์', 'มนุษย์หายใจใช้ออกซิเจน แต่ในอากาศมีไนโตรเจนมากที่สุด', 'อากาศ = ไนโตรเจน 78% + ออกซิเจน 21%', '["ชั้นบรรยากาศและสภาพอากาศ","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_010', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา', 'ปรากฏการณ์ ''จันทรุปราคา'' จะเกิดขึ้นได้เฉพาะในวันใดและวัตถุใดอยู่ตรงกลาง (ข้อที่ 10)', '["วันขึ้น 15 ค่ำ (ดวงจันทร์เต็มดวง) โดยมี ''โลก'' อยู่ตรงกลางระหว่างดวงอาทิตย์กับดวงจันทร์","วันแรม 15 ค่ำ โดยมีดวงจันทร์อยู่ตรงกลาง","วันขึ้น 8 ค่ำ โดยมีดวงอาทิตย์อยู่ตรงกลาง","วันแรม 1 ค่ำ โดยมีดาวพุธอยู่ตรงกลาง"]', 0, 'จันทรุปราคาเกิดเวลากลางคืนวันเพ็ญ โลกอยู่ตรงกลางบังเงาไม่ให้แสงอาทิตย์ไปกระทบดวงจันทร์', 'สุริยุปราคา = จันทร์อยู่กลาง / จันทรุปราคา = โลกอยู่กลาง', 'จันทรุปราคา = โลกอยู่กลาง กลางคืน วันเพ็ญ', '["ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_011', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'การสังเคราะห์ด้วยแสงและพืชศาสตร์', 'ในกระบวนการสังเคราะห์ด้วยแสงของพืช สารตั้งต้นและผลผลิตหลักที่ได้คือข้อใด (ข้อที่ 11)', '["สารตั้งต้น: น้ำ + แก๊สคาร์บอนไดออกไซด์ / ผลผลิต: น้ำตาลกลูโคส + แก๊สออกซิเจน","สารตั้งต้น: แก๊สออกซิเจน + แป้ง / ผลผลิต: น้ำ + แก๊สคาร์บอนไดออกไซด์","สารตั้งต้น: น้ำตาลกลูโคส + น้ำ / ผลผลิต: คลอโรฟิลล์","สารตั้งต้น: ปุ๋ยไนโตรเจน / ผลผลิต: แก๊สคาร์บอนไดออกไซด์"]', 0, 'พืชใช้แสง น้ำ และ CO2 สังเคราะห์น้ำตาลกลูโคสและปล่อย O2 ออกมา', 'อย่าสับสนกับการหายใจของพืชที่ดูด O2 แล้วปล่อย CO2', 'สังเคราะห์แสง = ดูด CO2 ปล่อย O2', '["การสังเคราะห์ด้วยแสงและพืชศาสตร์","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_012', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'ระบบหมุนเวียนเลือดและหัวใจ', 'เส้นเลือดชนิดใดที่นำเลือดที่มีแก๊สออกซิเจนสูงจากปอดกลับเข้าสู่หัวใจห้องบนซ้าย (ข้อที่ 12)', '["พัลโมนารีเวน (Pulmonary Vein)","พัลโมนารีอาร์เตอรี (Pulmonary Artery)","เอออร์ตา (Aorta)","เวนาคาวา (Vena Cava)"]', 0, 'พัลโมนารีเวนเป็นเส้นเลือดเวนเส้นเดียวที่ลำเลียงเลือดแดงมีออกซิเจนสูงจากปอดสู่หัวใจ', 'ปกติเส้นเลือดเวนจะมีเลือดดำ แต่พัลโมนารีเวนเป็นข้อยกเว้น', 'จากปอดเข้าหัวใจ = พัลโมนารีเวน (เลือดแดง)', '["ระบบหมุนเวียนเลือดและหัวใจ","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_013', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'ระบบย่อยอาหารและสารอาหาร', 'เอนไซม์ ''เปปซิน'' ในกระเพาะอาหารของมนุษย์ ทำหน้าที่ย่อยสารอาหารประเภทใดและทำงานได้ดีในสภาวะใด (ข้อที่ 13)', '["ย่อยโปรตีน ในสภาวะที่เป็นกรด (กรดไฮโดรคลอริก)","ย่อยไขมัน ในสภาวะที่เป็นเบส","ย่อยแป้ง ในสภาวะที่เป็นกลาง","ย่อยวิตามิน ในสภาวะที่เป็นกรด"]', 0, 'กระเพาะอาหารหลั่งกรดไฮโดรคลอริกเพื่อให้เอนไซม์เปปซินย่อยโปรตีนได้อย่างมีประสิทธิภาพ', 'เอนไซม์ในกระเพาะชอบกรด ส่วนในลำไส้เล็กชอบเบส', 'กระเพาะ = กรด + ย่อยโปรตีน', '["ระบบย่อยอาหารและสารอาหาร","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_014', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'โซ่อาหารและกฎ 10% พลังงาน', 'สิ่งมีชีวิตใดในระบบนิเวศที่มีบทบาทสำคัญในการเปลี่ยนอินทรียสารให้กลับคืนเป็นแร่ธาตุในดิน (ข้อที่ 14)', '["ผู้ย่อยสลายสารอินทรีย์ (Decomposers) เช่น เห็ด รา แบคทีเรีย","ผู้ผลิต (Producers) เช่น สาหร่ายและพืชสีเขียว","ผู้บริโภคซากสัตว์ (Scavengers) เช่น แร้ง","ผู้บริโภคลำดับสูงสุด"]', 0, 'เห็ด รา และแบคทีเรีย ย่อยสลายซากพืชซากสัตว์คืนธาตุอาหารลงสู่ดินและวัฏจักร', 'สัตว์กินซาก เช่น แร้ง เป็นผู้บริโภค ไม่ใช่ผู้ย่อยสลายอินทรียสารระดับโมเลกุล', 'ย่อยสลายคืนสู่ดิน = เห็ด รา แบคทีเรีย', '["โซ่อาหารและกฎ 10% พลังงาน","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_015', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'แรงพยุงและความหนาแน่น', 'วัตถุก้อนหนึ่งมีมวล 80 กรัม ปริมาตร 100 ลูกบาศก์เซนติเมตร เมื่อนำไปลอยในน้ำบริสุทธิ์จะมีสภาพเป็นอย่างไร (ข้อที่ 15)', '["ลอยน้ำ โดยมีปริมาตรจมน้ำ 80% และโผล่พ้นน้ำ 20%","จมลงสู่ก้นภาชนะทันที","ลอยน้ำ โดยมีปริมาตรจมน้ำ 20% และโผล่พ้นน้ำ 80%","ลอยปริ่มน้ำพอดี 100%"]', 0, 'ความหนาแน่นวัตถุ = 80/100 = 0.8 g/cm³ น้อยกว่าน้ำ (1.0) จึงลอย และมีสัดส่วนจม 80%', 'ความหนาแน่นวัตถุคือเปอร์เซ็นต์ส่วนที่จมน้ำ', 'ความหนาแน่น = สัดส่วนปริมาตรที่จมน้ำ', '["แรงพยุงและความหนาแน่น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_016', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'วงจรไฟฟ้าและกฎของโอห์ม', 'เมื่อนำหลอดไฟ 3 หลอดมาต่อกันแบบ ''ขนาน'' หากหลอดไฟดวงหนึ่งขาด หลอดไฟที่เหลือจะเป็นอย่างไร (ข้อที่ 16)', '["หลอดไฟที่เหลือยังคงสว่างตามปกติ","หลอดไฟที่เหลือจะดับทั้งหมดทันที","หลอดไฟที่เหลือจะสว่างลดลงครึ่งหนึ่ง","หลอดไฟที่เหลือจะระเบิด"]', 0, 'การต่อแบบขนาน กระแสไฟฟ้ามีทางเดินแยกกันเป็นอิสระ เมื่อหลอดหนึ่งขาด วงจรอื่นยังคงครบวงจร', 'ถ้าต่อแบบอนุกรม หลอดหนึ่งขาดจะดับทั้งหมด', 'ต่อขนาน = วงจรบ้าน = ดับ 1 ดวง ดวงอื่นยังสว่าง', '["วงจรไฟฟ้าและกฎของโอห์ม","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_017', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'แสง เลนส์ และการมองเห็น', 'ปรากฏการณ์ ''รุ้งกินน้ำ'' เกิดจากแสงอาทิตย์กระทบกับละอองน้ำในอากาศผ่านกระบวนการใดตามลำดับ (ข้อที่ 17)', '["การหักเห -> การสะท้อนกลับหมด -> การกระจายของแสง","การแทรกสอด -> การเลี้ยวเบน -> การดูดกลืน","การสะท้อนปกติ -> การรวมแสง","การแผ่รังสี -> การพาความร้อน"]', 0, 'แสงแดดส่องเข้าละอองน้ำ หักเหและกระจายแสงสี แล้วสะท้อนกลับหมดภายในหยดน้ำออกมาสู่สายตา', 'รุ้งกินน้ำจะเกิดทิศตรงข้ามกับดวงอาทิตย์เสมอ', 'รุ้งกินน้ำ = หักเห + กระจายแสง + สะท้อนกลับหมด', '["แสง เลนส์ และการมองเห็น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_018', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'การแยกสารและโครมาโทกราฟี', 'วิธีใดเหมาะสมที่สุดในการแยก ''เกลือแกง'' ออกจาก ''น้ำทะเล'' (ข้อที่ 18)', '["การระเหยแห้ง (Evaporation)","การกรองด้วยกระดาษกรอง","การใช้แม่เหล็กดูด","การสกัดด้วยตัวทำละลาย"]', 0, 'เกลือละลายเป็นเนื้อเดียวกับน้ำ ต้องใช้ความร้อนระเหยน้ำออกไปจนเหลือผลึกเกลือตกค้าง', 'การกรองไม่สามารถแยกสารที่ละลายเป็นเนื้อเดียวกันได้', 'น้ำเกลือระเหยแห้งได้ผลึกเกลือ', '["การแยกสารและโครมาโทกราฟี","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_019', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'ชั้นบรรยากาศและสภาพอากาศ', 'แก๊สชนิดใดมีสัดส่วนปริมาณมากที่สุดในบรรยากาศของโลก (ข้อที่ 19)', '["แก๊สไนโตรเจน (ประมาณ 78%)","แก๊สออกซิเจน (ประมาณ 21%)","แก๊สคาร์บอนไดออกไซด์ (ประมาณ 0.04%)","แก๊สฮีเลียม"]', 0, 'อากาศมีแก๊สไนโตรเจนมากที่สุด 78% รองลงมาคือออกซิเจน 21% และอาร์กอน/คาร์บอนไดออกไซด์', 'มนุษย์หายใจใช้ออกซิเจน แต่ในอากาศมีไนโตรเจนมากที่สุด', 'อากาศ = ไนโตรเจน 78% + ออกซิเจน 21%', '["ชั้นบรรยากาศและสภาพอากาศ","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_020', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา', 'ปรากฏการณ์ ''จันทรุปราคา'' จะเกิดขึ้นได้เฉพาะในวันใดและวัตถุใดอยู่ตรงกลาง (ข้อที่ 20)', '["วันขึ้น 15 ค่ำ (ดวงจันทร์เต็มดวง) โดยมี ''โลก'' อยู่ตรงกลางระหว่างดวงอาทิตย์กับดวงจันทร์","วันแรม 15 ค่ำ โดยมีดวงจันทร์อยู่ตรงกลาง","วันขึ้น 8 ค่ำ โดยมีดวงอาทิตย์อยู่ตรงกลาง","วันแรม 1 ค่ำ โดยมีดาวพุธอยู่ตรงกลาง"]', 0, 'จันทรุปราคาเกิดเวลากลางคืนวันเพ็ญ โลกอยู่ตรงกลางบังเงาไม่ให้แสงอาทิตย์ไปกระทบดวงจันทร์', 'สุริยุปราคา = จันทร์อยู่กลาง / จันทรุปราคา = โลกอยู่กลาง', 'จันทรุปราคา = โลกอยู่กลาง กลางคืน วันเพ็ญ', '["ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_021', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'การสังเคราะห์ด้วยแสงและพืชศาสตร์', 'ในกระบวนการสังเคราะห์ด้วยแสงของพืช สารตั้งต้นและผลผลิตหลักที่ได้คือข้อใด (ข้อที่ 21)', '["สารตั้งต้น: น้ำ + แก๊สคาร์บอนไดออกไซด์ / ผลผลิต: น้ำตาลกลูโคส + แก๊สออกซิเจน","สารตั้งต้น: แก๊สออกซิเจน + แป้ง / ผลผลิต: น้ำ + แก๊สคาร์บอนไดออกไซด์","สารตั้งต้น: น้ำตาลกลูโคส + น้ำ / ผลผลิต: คลอโรฟิลล์","สารตั้งต้น: ปุ๋ยไนโตรเจน / ผลผลิต: แก๊สคาร์บอนไดออกไซด์"]', 0, 'พืชใช้แสง น้ำ และ CO2 สังเคราะห์น้ำตาลกลูโคสและปล่อย O2 ออกมา', 'อย่าสับสนกับการหายใจของพืชที่ดูด O2 แล้วปล่อย CO2', 'สังเคราะห์แสง = ดูด CO2 ปล่อย O2', '["การสังเคราะห์ด้วยแสงและพืชศาสตร์","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_022', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'ระบบหมุนเวียนเลือดและหัวใจ', 'เส้นเลือดชนิดใดที่นำเลือดที่มีแก๊สออกซิเจนสูงจากปอดกลับเข้าสู่หัวใจห้องบนซ้าย (ข้อที่ 22)', '["พัลโมนารีเวน (Pulmonary Vein)","พัลโมนารีอาร์เตอรี (Pulmonary Artery)","เอออร์ตา (Aorta)","เวนาคาวา (Vena Cava)"]', 0, 'พัลโมนารีเวนเป็นเส้นเลือดเวนเส้นเดียวที่ลำเลียงเลือดแดงมีออกซิเจนสูงจากปอดสู่หัวใจ', 'ปกติเส้นเลือดเวนจะมีเลือดดำ แต่พัลโมนารีเวนเป็นข้อยกเว้น', 'จากปอดเข้าหัวใจ = พัลโมนารีเวน (เลือดแดง)', '["ระบบหมุนเวียนเลือดและหัวใจ","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_023', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'ระบบย่อยอาหารและสารอาหาร', 'เอนไซม์ ''เปปซิน'' ในกระเพาะอาหารของมนุษย์ ทำหน้าที่ย่อยสารอาหารประเภทใดและทำงานได้ดีในสภาวะใด (ข้อที่ 23)', '["ย่อยโปรตีน ในสภาวะที่เป็นกรด (กรดไฮโดรคลอริก)","ย่อยไขมัน ในสภาวะที่เป็นเบส","ย่อยแป้ง ในสภาวะที่เป็นกลาง","ย่อยวิตามิน ในสภาวะที่เป็นกรด"]', 0, 'กระเพาะอาหารหลั่งกรดไฮโดรคลอริกเพื่อให้เอนไซม์เปปซินย่อยโปรตีนได้อย่างมีประสิทธิภาพ', 'เอนไซม์ในกระเพาะชอบกรด ส่วนในลำไส้เล็กชอบเบส', 'กระเพาะ = กรด + ย่อยโปรตีน', '["ระบบย่อยอาหารและสารอาหาร","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_024', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'โซ่อาหารและกฎ 10% พลังงาน', 'สิ่งมีชีวิตใดในระบบนิเวศที่มีบทบาทสำคัญในการเปลี่ยนอินทรียสารให้กลับคืนเป็นแร่ธาตุในดิน (ข้อที่ 24)', '["ผู้ย่อยสลายสารอินทรีย์ (Decomposers) เช่น เห็ด รา แบคทีเรีย","ผู้ผลิต (Producers) เช่น สาหร่ายและพืชสีเขียว","ผู้บริโภคซากสัตว์ (Scavengers) เช่น แร้ง","ผู้บริโภคลำดับสูงสุด"]', 0, 'เห็ด รา และแบคทีเรีย ย่อยสลายซากพืชซากสัตว์คืนธาตุอาหารลงสู่ดินและวัฏจักร', 'สัตว์กินซาก เช่น แร้ง เป็นผู้บริโภค ไม่ใช่ผู้ย่อยสลายอินทรียสารระดับโมเลกุล', 'ย่อยสลายคืนสู่ดิน = เห็ด รา แบคทีเรีย', '["โซ่อาหารและกฎ 10% พลังงาน","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_025', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'แรงพยุงและความหนาแน่น', 'วัตถุก้อนหนึ่งมีมวล 80 กรัม ปริมาตร 100 ลูกบาศก์เซนติเมตร เมื่อนำไปลอยในน้ำบริสุทธิ์จะมีสภาพเป็นอย่างไร (ข้อที่ 25)', '["ลอยน้ำ โดยมีปริมาตรจมน้ำ 80% และโผล่พ้นน้ำ 20%","จมลงสู่ก้นภาชนะทันที","ลอยน้ำ โดยมีปริมาตรจมน้ำ 20% และโผล่พ้นน้ำ 80%","ลอยปริ่มน้ำพอดี 100%"]', 0, 'ความหนาแน่นวัตถุ = 80/100 = 0.8 g/cm³ น้อยกว่าน้ำ (1.0) จึงลอย และมีสัดส่วนจม 80%', 'ความหนาแน่นวัตถุคือเปอร์เซ็นต์ส่วนที่จมน้ำ', 'ความหนาแน่น = สัดส่วนปริมาตรที่จมน้ำ', '["แรงพยุงและความหนาแน่น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_026', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'วงจรไฟฟ้าและกฎของโอห์ม', 'เมื่อนำหลอดไฟ 3 หลอดมาต่อกันแบบ ''ขนาน'' หากหลอดไฟดวงหนึ่งขาด หลอดไฟที่เหลือจะเป็นอย่างไร (ข้อที่ 26)', '["หลอดไฟที่เหลือยังคงสว่างตามปกติ","หลอดไฟที่เหลือจะดับทั้งหมดทันที","หลอดไฟที่เหลือจะสว่างลดลงครึ่งหนึ่ง","หลอดไฟที่เหลือจะระเบิด"]', 0, 'การต่อแบบขนาน กระแสไฟฟ้ามีทางเดินแยกกันเป็นอิสระ เมื่อหลอดหนึ่งขาด วงจรอื่นยังคงครบวงจร', 'ถ้าต่อแบบอนุกรม หลอดหนึ่งขาดจะดับทั้งหมด', 'ต่อขนาน = วงจรบ้าน = ดับ 1 ดวง ดวงอื่นยังสว่าง', '["วงจรไฟฟ้าและกฎของโอห์ม","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_027', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'แสง เลนส์ และการมองเห็น', 'ปรากฏการณ์ ''รุ้งกินน้ำ'' เกิดจากแสงอาทิตย์กระทบกับละอองน้ำในอากาศผ่านกระบวนการใดตามลำดับ (ข้อที่ 27)', '["การหักเห -> การสะท้อนกลับหมด -> การกระจายของแสง","การแทรกสอด -> การเลี้ยวเบน -> การดูดกลืน","การสะท้อนปกติ -> การรวมแสง","การแผ่รังสี -> การพาความร้อน"]', 0, 'แสงแดดส่องเข้าละอองน้ำ หักเหและกระจายแสงสี แล้วสะท้อนกลับหมดภายในหยดน้ำออกมาสู่สายตา', 'รุ้งกินน้ำจะเกิดทิศตรงข้ามกับดวงอาทิตย์เสมอ', 'รุ้งกินน้ำ = หักเห + กระจายแสง + สะท้อนกลับหมด', '["แสง เลนส์ และการมองเห็น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_028', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'การแยกสารและโครมาโทกราฟี', 'วิธีใดเหมาะสมที่สุดในการแยก ''เกลือแกง'' ออกจาก ''น้ำทะเล'' (ข้อที่ 28)', '["การระเหยแห้ง (Evaporation)","การกรองด้วยกระดาษกรอง","การใช้แม่เหล็กดูด","การสกัดด้วยตัวทำละลาย"]', 0, 'เกลือละลายเป็นเนื้อเดียวกับน้ำ ต้องใช้ความร้อนระเหยน้ำออกไปจนเหลือผลึกเกลือตกค้าง', 'การกรองไม่สามารถแยกสารที่ละลายเป็นเนื้อเดียวกันได้', 'น้ำเกลือระเหยแห้งได้ผลึกเกลือ', '["การแยกสารและโครมาโทกราฟี","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_029', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'ชั้นบรรยากาศและสภาพอากาศ', 'แก๊สชนิดใดมีสัดส่วนปริมาณมากที่สุดในบรรยากาศของโลก (ข้อที่ 29)', '["แก๊สไนโตรเจน (ประมาณ 78%)","แก๊สออกซิเจน (ประมาณ 21%)","แก๊สคาร์บอนไดออกไซด์ (ประมาณ 0.04%)","แก๊สฮีเลียม"]', 0, 'อากาศมีแก๊สไนโตรเจนมากที่สุด 78% รองลงมาคือออกซิเจน 21% และอาร์กอน/คาร์บอนไดออกไซด์', 'มนุษย์หายใจใช้ออกซิเจน แต่ในอากาศมีไนโตรเจนมากที่สุด', 'อากาศ = ไนโตรเจน 78% + ออกซิเจน 21%', '["ชั้นบรรยากาศและสภาพอากาศ","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_030', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา', 'ปรากฏการณ์ ''จันทรุปราคา'' จะเกิดขึ้นได้เฉพาะในวันใดและวัตถุใดอยู่ตรงกลาง (ข้อที่ 30)', '["วันขึ้น 15 ค่ำ (ดวงจันทร์เต็มดวง) โดยมี ''โลก'' อยู่ตรงกลางระหว่างดวงอาทิตย์กับดวงจันทร์","วันแรม 15 ค่ำ โดยมีดวงจันทร์อยู่ตรงกลาง","วันขึ้น 8 ค่ำ โดยมีดวงอาทิตย์อยู่ตรงกลาง","วันแรม 1 ค่ำ โดยมีดาวพุธอยู่ตรงกลาง"]', 0, 'จันทรุปราคาเกิดเวลากลางคืนวันเพ็ญ โลกอยู่ตรงกลางบังเงาไม่ให้แสงอาทิตย์ไปกระทบดวงจันทร์', 'สุริยุปราคา = จันทร์อยู่กลาง / จันทรุปราคา = โลกอยู่กลาง', 'จันทรุปราคา = โลกอยู่กลาง กลางคืน วันเพ็ญ', '["ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_031', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'การสังเคราะห์ด้วยแสงและพืชศาสตร์', 'ในกระบวนการสังเคราะห์ด้วยแสงของพืช สารตั้งต้นและผลผลิตหลักที่ได้คือข้อใด (ข้อที่ 31)', '["สารตั้งต้น: น้ำ + แก๊สคาร์บอนไดออกไซด์ / ผลผลิต: น้ำตาลกลูโคส + แก๊สออกซิเจน","สารตั้งต้น: แก๊สออกซิเจน + แป้ง / ผลผลิต: น้ำ + แก๊สคาร์บอนไดออกไซด์","สารตั้งต้น: น้ำตาลกลูโคส + น้ำ / ผลผลิต: คลอโรฟิลล์","สารตั้งต้น: ปุ๋ยไนโตรเจน / ผลผลิต: แก๊สคาร์บอนไดออกไซด์"]', 0, 'พืชใช้แสง น้ำ และ CO2 สังเคราะห์น้ำตาลกลูโคสและปล่อย O2 ออกมา', 'อย่าสับสนกับการหายใจของพืชที่ดูด O2 แล้วปล่อย CO2', 'สังเคราะห์แสง = ดูด CO2 ปล่อย O2', '["การสังเคราะห์ด้วยแสงและพืชศาสตร์","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_032', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'ระบบหมุนเวียนเลือดและหัวใจ', 'เส้นเลือดชนิดใดที่นำเลือดที่มีแก๊สออกซิเจนสูงจากปอดกลับเข้าสู่หัวใจห้องบนซ้าย (ข้อที่ 32)', '["พัลโมนารีเวน (Pulmonary Vein)","พัลโมนารีอาร์เตอรี (Pulmonary Artery)","เอออร์ตา (Aorta)","เวนาคาวา (Vena Cava)"]', 0, 'พัลโมนารีเวนเป็นเส้นเลือดเวนเส้นเดียวที่ลำเลียงเลือดแดงมีออกซิเจนสูงจากปอดสู่หัวใจ', 'ปกติเส้นเลือดเวนจะมีเลือดดำ แต่พัลโมนารีเวนเป็นข้อยกเว้น', 'จากปอดเข้าหัวใจ = พัลโมนารีเวน (เลือดแดง)', '["ระบบหมุนเวียนเลือดและหัวใจ","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_033', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ระบบย่อยอาหารและสารอาหาร', 'เอนไซม์ ''เปปซิน'' ในกระเพาะอาหารของมนุษย์ ทำหน้าที่ย่อยสารอาหารประเภทใดและทำงานได้ดีในสภาวะใด (ข้อที่ 33)', '["ย่อยโปรตีน ในสภาวะที่เป็นกรด (กรดไฮโดรคลอริก)","ย่อยไขมัน ในสภาวะที่เป็นเบส","ย่อยแป้ง ในสภาวะที่เป็นกลาง","ย่อยวิตามิน ในสภาวะที่เป็นกรด"]', 0, 'กระเพาะอาหารหลั่งกรดไฮโดรคลอริกเพื่อให้เอนไซม์เปปซินย่อยโปรตีนได้อย่างมีประสิทธิภาพ', 'เอนไซม์ในกระเพาะชอบกรด ส่วนในลำไส้เล็กชอบเบส', 'กระเพาะ = กรด + ย่อยโปรตีน', '["ระบบย่อยอาหารและสารอาหาร","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_034', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'โซ่อาหารและกฎ 10% พลังงาน', 'สิ่งมีชีวิตใดในระบบนิเวศที่มีบทบาทสำคัญในการเปลี่ยนอินทรียสารให้กลับคืนเป็นแร่ธาตุในดิน (ข้อที่ 34)', '["ผู้ย่อยสลายสารอินทรีย์ (Decomposers) เช่น เห็ด รา แบคทีเรีย","ผู้ผลิต (Producers) เช่น สาหร่ายและพืชสีเขียว","ผู้บริโภคซากสัตว์ (Scavengers) เช่น แร้ง","ผู้บริโภคลำดับสูงสุด"]', 0, 'เห็ด รา และแบคทีเรีย ย่อยสลายซากพืชซากสัตว์คืนธาตุอาหารลงสู่ดินและวัฏจักร', 'สัตว์กินซาก เช่น แร้ง เป็นผู้บริโภค ไม่ใช่ผู้ย่อยสลายอินทรียสารระดับโมเลกุล', 'ย่อยสลายคืนสู่ดิน = เห็ด รา แบคทีเรีย', '["โซ่อาหารและกฎ 10% พลังงาน","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_035', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'แรงพยุงและความหนาแน่น', 'วัตถุก้อนหนึ่งมีมวล 80 กรัม ปริมาตร 100 ลูกบาศก์เซนติเมตร เมื่อนำไปลอยในน้ำบริสุทธิ์จะมีสภาพเป็นอย่างไร (ข้อที่ 35)', '["ลอยน้ำ โดยมีปริมาตรจมน้ำ 80% และโผล่พ้นน้ำ 20%","จมลงสู่ก้นภาชนะทันที","ลอยน้ำ โดยมีปริมาตรจมน้ำ 20% และโผล่พ้นน้ำ 80%","ลอยปริ่มน้ำพอดี 100%"]', 0, 'ความหนาแน่นวัตถุ = 80/100 = 0.8 g/cm³ น้อยกว่าน้ำ (1.0) จึงลอย และมีสัดส่วนจม 80%', 'ความหนาแน่นวัตถุคือเปอร์เซ็นต์ส่วนที่จมน้ำ', 'ความหนาแน่น = สัดส่วนปริมาตรที่จมน้ำ', '["แรงพยุงและความหนาแน่น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_036', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'วงจรไฟฟ้าและกฎของโอห์ม', 'เมื่อนำหลอดไฟ 3 หลอดมาต่อกันแบบ ''ขนาน'' หากหลอดไฟดวงหนึ่งขาด หลอดไฟที่เหลือจะเป็นอย่างไร (ข้อที่ 36)', '["หลอดไฟที่เหลือยังคงสว่างตามปกติ","หลอดไฟที่เหลือจะดับทั้งหมดทันที","หลอดไฟที่เหลือจะสว่างลดลงครึ่งหนึ่ง","หลอดไฟที่เหลือจะระเบิด"]', 0, 'การต่อแบบขนาน กระแสไฟฟ้ามีทางเดินแยกกันเป็นอิสระ เมื่อหลอดหนึ่งขาด วงจรอื่นยังคงครบวงจร', 'ถ้าต่อแบบอนุกรม หลอดหนึ่งขาดจะดับทั้งหมด', 'ต่อขนาน = วงจรบ้าน = ดับ 1 ดวง ดวงอื่นยังสว่าง', '["วงจรไฟฟ้าและกฎของโอห์ม","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_037', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'แสง เลนส์ และการมองเห็น', 'ปรากฏการณ์ ''รุ้งกินน้ำ'' เกิดจากแสงอาทิตย์กระทบกับละอองน้ำในอากาศผ่านกระบวนการใดตามลำดับ (ข้อที่ 37)', '["การหักเห -> การสะท้อนกลับหมด -> การกระจายของแสง","การแทรกสอด -> การเลี้ยวเบน -> การดูดกลืน","การสะท้อนปกติ -> การรวมแสง","การแผ่รังสี -> การพาความร้อน"]', 0, 'แสงแดดส่องเข้าละอองน้ำ หักเหและกระจายแสงสี แล้วสะท้อนกลับหมดภายในหยดน้ำออกมาสู่สายตา', 'รุ้งกินน้ำจะเกิดทิศตรงข้ามกับดวงอาทิตย์เสมอ', 'รุ้งกินน้ำ = หักเห + กระจายแสง + สะท้อนกลับหมด', '["แสง เลนส์ และการมองเห็น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_038', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'การแยกสารและโครมาโทกราฟี', 'วิธีใดเหมาะสมที่สุดในการแยก ''เกลือแกง'' ออกจาก ''น้ำทะเล'' (ข้อที่ 38)', '["การระเหยแห้ง (Evaporation)","การกรองด้วยกระดาษกรอง","การใช้แม่เหล็กดูด","การสกัดด้วยตัวทำละลาย"]', 0, 'เกลือละลายเป็นเนื้อเดียวกับน้ำ ต้องใช้ความร้อนระเหยน้ำออกไปจนเหลือผลึกเกลือตกค้าง', 'การกรองไม่สามารถแยกสารที่ละลายเป็นเนื้อเดียวกันได้', 'น้ำเกลือระเหยแห้งได้ผลึกเกลือ', '["การแยกสารและโครมาโทกราฟี","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_039', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ชั้นบรรยากาศและสภาพอากาศ', 'แก๊สชนิดใดมีสัดส่วนปริมาณมากที่สุดในบรรยากาศของโลก (ข้อที่ 39)', '["แก๊สไนโตรเจน (ประมาณ 78%)","แก๊สออกซิเจน (ประมาณ 21%)","แก๊สคาร์บอนไดออกไซด์ (ประมาณ 0.04%)","แก๊สฮีเลียม"]', 0, 'อากาศมีแก๊สไนโตรเจนมากที่สุด 78% รองลงมาคือออกซิเจน 21% และอาร์กอน/คาร์บอนไดออกไซด์', 'มนุษย์หายใจใช้ออกซิเจน แต่ในอากาศมีไนโตรเจนมากที่สุด', 'อากาศ = ไนโตรเจน 78% + ออกซิเจน 21%', '["ชั้นบรรยากาศและสภาพอากาศ","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_040', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา', 'ปรากฏการณ์ ''จันทรุปราคา'' จะเกิดขึ้นได้เฉพาะในวันใดและวัตถุใดอยู่ตรงกลาง (ข้อที่ 40)', '["วันขึ้น 15 ค่ำ (ดวงจันทร์เต็มดวง) โดยมี ''โลก'' อยู่ตรงกลางระหว่างดวงอาทิตย์กับดวงจันทร์","วันแรม 15 ค่ำ โดยมีดวงจันทร์อยู่ตรงกลาง","วันขึ้น 8 ค่ำ โดยมีดวงอาทิตย์อยู่ตรงกลาง","วันแรม 1 ค่ำ โดยมีดาวพุธอยู่ตรงกลาง"]', 0, 'จันทรุปราคาเกิดเวลากลางคืนวันเพ็ญ โลกอยู่ตรงกลางบังเงาไม่ให้แสงอาทิตย์ไปกระทบดวงจันทร์', 'สุริยุปราคา = จันทร์อยู่กลาง / จันทรุปราคา = โลกอยู่กลาง', 'จันทรุปราคา = โลกอยู่กลาง กลางคืน วันเพ็ญ', '["ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_041', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'การสังเคราะห์ด้วยแสงและพืชศาสตร์', 'ในกระบวนการสังเคราะห์ด้วยแสงของพืช สารตั้งต้นและผลผลิตหลักที่ได้คือข้อใด (ข้อที่ 41)', '["สารตั้งต้น: น้ำ + แก๊สคาร์บอนไดออกไซด์ / ผลผลิต: น้ำตาลกลูโคส + แก๊สออกซิเจน","สารตั้งต้น: แก๊สออกซิเจน + แป้ง / ผลผลิต: น้ำ + แก๊สคาร์บอนไดออกไซด์","สารตั้งต้น: น้ำตาลกลูโคส + น้ำ / ผลผลิต: คลอโรฟิลล์","สารตั้งต้น: ปุ๋ยไนโตรเจน / ผลผลิต: แก๊สคาร์บอนไดออกไซด์"]', 0, 'พืชใช้แสง น้ำ และ CO2 สังเคราะห์น้ำตาลกลูโคสและปล่อย O2 ออกมา', 'อย่าสับสนกับการหายใจของพืชที่ดูด O2 แล้วปล่อย CO2', 'สังเคราะห์แสง = ดูด CO2 ปล่อย O2', '["การสังเคราะห์ด้วยแสงและพืชศาสตร์","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_042', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'ระบบหมุนเวียนเลือดและหัวใจ', 'เส้นเลือดชนิดใดที่นำเลือดที่มีแก๊สออกซิเจนสูงจากปอดกลับเข้าสู่หัวใจห้องบนซ้าย (ข้อที่ 42)', '["พัลโมนารีเวน (Pulmonary Vein)","พัลโมนารีอาร์เตอรี (Pulmonary Artery)","เอออร์ตา (Aorta)","เวนาคาวา (Vena Cava)"]', 0, 'พัลโมนารีเวนเป็นเส้นเลือดเวนเส้นเดียวที่ลำเลียงเลือดแดงมีออกซิเจนสูงจากปอดสู่หัวใจ', 'ปกติเส้นเลือดเวนจะมีเลือดดำ แต่พัลโมนารีเวนเป็นข้อยกเว้น', 'จากปอดเข้าหัวใจ = พัลโมนารีเวน (เลือดแดง)', '["ระบบหมุนเวียนเลือดและหัวใจ","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_043', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'ระบบย่อยอาหารและสารอาหาร', 'เอนไซม์ ''เปปซิน'' ในกระเพาะอาหารของมนุษย์ ทำหน้าที่ย่อยสารอาหารประเภทใดและทำงานได้ดีในสภาวะใด (ข้อที่ 43)', '["ย่อยโปรตีน ในสภาวะที่เป็นกรด (กรดไฮโดรคลอริก)","ย่อยไขมัน ในสภาวะที่เป็นเบส","ย่อยแป้ง ในสภาวะที่เป็นกลาง","ย่อยวิตามิน ในสภาวะที่เป็นกรด"]', 0, 'กระเพาะอาหารหลั่งกรดไฮโดรคลอริกเพื่อให้เอนไซม์เปปซินย่อยโปรตีนได้อย่างมีประสิทธิภาพ', 'เอนไซม์ในกระเพาะชอบกรด ส่วนในลำไส้เล็กชอบเบส', 'กระเพาะ = กรด + ย่อยโปรตีน', '["ระบบย่อยอาหารและสารอาหาร","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_044', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'โซ่อาหารและกฎ 10% พลังงาน', 'สิ่งมีชีวิตใดในระบบนิเวศที่มีบทบาทสำคัญในการเปลี่ยนอินทรียสารให้กลับคืนเป็นแร่ธาตุในดิน (ข้อที่ 44)', '["ผู้ย่อยสลายสารอินทรีย์ (Decomposers) เช่น เห็ด รา แบคทีเรีย","ผู้ผลิต (Producers) เช่น สาหร่ายและพืชสีเขียว","ผู้บริโภคซากสัตว์ (Scavengers) เช่น แร้ง","ผู้บริโภคลำดับสูงสุด"]', 0, 'เห็ด รา และแบคทีเรีย ย่อยสลายซากพืชซากสัตว์คืนธาตุอาหารลงสู่ดินและวัฏจักร', 'สัตว์กินซาก เช่น แร้ง เป็นผู้บริโภค ไม่ใช่ผู้ย่อยสลายอินทรียสารระดับโมเลกุล', 'ย่อยสลายคืนสู่ดิน = เห็ด รา แบคทีเรีย', '["โซ่อาหารและกฎ 10% พลังงาน","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_045', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'แรงพยุงและความหนาแน่น', 'วัตถุก้อนหนึ่งมีมวล 80 กรัม ปริมาตร 100 ลูกบาศก์เซนติเมตร เมื่อนำไปลอยในน้ำบริสุทธิ์จะมีสภาพเป็นอย่างไร (ข้อที่ 45)', '["ลอยน้ำ โดยมีปริมาตรจมน้ำ 80% และโผล่พ้นน้ำ 20%","จมลงสู่ก้นภาชนะทันที","ลอยน้ำ โดยมีปริมาตรจมน้ำ 20% และโผล่พ้นน้ำ 80%","ลอยปริ่มน้ำพอดี 100%"]', 0, 'ความหนาแน่นวัตถุ = 80/100 = 0.8 g/cm³ น้อยกว่าน้ำ (1.0) จึงลอย และมีสัดส่วนจม 80%', 'ความหนาแน่นวัตถุคือเปอร์เซ็นต์ส่วนที่จมน้ำ', 'ความหนาแน่น = สัดส่วนปริมาตรที่จมน้ำ', '["แรงพยุงและความหนาแน่น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_046', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'วงจรไฟฟ้าและกฎของโอห์ม', 'เมื่อนำหลอดไฟ 3 หลอดมาต่อกันแบบ ''ขนาน'' หากหลอดไฟดวงหนึ่งขาด หลอดไฟที่เหลือจะเป็นอย่างไร (ข้อที่ 46)', '["หลอดไฟที่เหลือยังคงสว่างตามปกติ","หลอดไฟที่เหลือจะดับทั้งหมดทันที","หลอดไฟที่เหลือจะสว่างลดลงครึ่งหนึ่ง","หลอดไฟที่เหลือจะระเบิด"]', 0, 'การต่อแบบขนาน กระแสไฟฟ้ามีทางเดินแยกกันเป็นอิสระ เมื่อหลอดหนึ่งขาด วงจรอื่นยังคงครบวงจร', 'ถ้าต่อแบบอนุกรม หลอดหนึ่งขาดจะดับทั้งหมด', 'ต่อขนาน = วงจรบ้าน = ดับ 1 ดวง ดวงอื่นยังสว่าง', '["วงจรไฟฟ้าและกฎของโอห์ม","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_047', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'แสง เลนส์ และการมองเห็น', 'ปรากฏการณ์ ''รุ้งกินน้ำ'' เกิดจากแสงอาทิตย์กระทบกับละอองน้ำในอากาศผ่านกระบวนการใดตามลำดับ (ข้อที่ 47)', '["การหักเห -> การสะท้อนกลับหมด -> การกระจายของแสง","การแทรกสอด -> การเลี้ยวเบน -> การดูดกลืน","การสะท้อนปกติ -> การรวมแสง","การแผ่รังสี -> การพาความร้อน"]', 0, 'แสงแดดส่องเข้าละอองน้ำ หักเหและกระจายแสงสี แล้วสะท้อนกลับหมดภายในหยดน้ำออกมาสู่สายตา', 'รุ้งกินน้ำจะเกิดทิศตรงข้ามกับดวงอาทิตย์เสมอ', 'รุ้งกินน้ำ = หักเห + กระจายแสง + สะท้อนกลับหมด', '["แสง เลนส์ และการมองเห็น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_048', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'การแยกสารและโครมาโทกราฟี', 'วิธีใดเหมาะสมที่สุดในการแยก ''เกลือแกง'' ออกจาก ''น้ำทะเล'' (ข้อที่ 48)', '["การระเหยแห้ง (Evaporation)","การกรองด้วยกระดาษกรอง","การใช้แม่เหล็กดูด","การสกัดด้วยตัวทำละลาย"]', 0, 'เกลือละลายเป็นเนื้อเดียวกับน้ำ ต้องใช้ความร้อนระเหยน้ำออกไปจนเหลือผลึกเกลือตกค้าง', 'การกรองไม่สามารถแยกสารที่ละลายเป็นเนื้อเดียวกันได้', 'น้ำเกลือระเหยแห้งได้ผลึกเกลือ', '["การแยกสารและโครมาโทกราฟี","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_049', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'ชั้นบรรยากาศและสภาพอากาศ', 'แก๊สชนิดใดมีสัดส่วนปริมาณมากที่สุดในบรรยากาศของโลก (ข้อที่ 49)', '["แก๊สไนโตรเจน (ประมาณ 78%)","แก๊สออกซิเจน (ประมาณ 21%)","แก๊สคาร์บอนไดออกไซด์ (ประมาณ 0.04%)","แก๊สฮีเลียม"]', 0, 'อากาศมีแก๊สไนโตรเจนมากที่สุด 78% รองลงมาคือออกซิเจน 21% และอาร์กอน/คาร์บอนไดออกไซด์', 'มนุษย์หายใจใช้ออกซิเจน แต่ในอากาศมีไนโตรเจนมากที่สุด', 'อากาศ = ไนโตรเจน 78% + ออกซิเจน 21%', '["ชั้นบรรยากาศและสภาพอากาศ","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_050', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา', 'ปรากฏการณ์ ''จันทรุปราคา'' จะเกิดขึ้นได้เฉพาะในวันใดและวัตถุใดอยู่ตรงกลาง (ข้อที่ 50)', '["วันขึ้น 15 ค่ำ (ดวงจันทร์เต็มดวง) โดยมี ''โลก'' อยู่ตรงกลางระหว่างดวงอาทิตย์กับดวงจันทร์","วันแรม 15 ค่ำ โดยมีดวงจันทร์อยู่ตรงกลาง","วันขึ้น 8 ค่ำ โดยมีดวงอาทิตย์อยู่ตรงกลาง","วันแรม 1 ค่ำ โดยมีดาวพุธอยู่ตรงกลาง"]', 0, 'จันทรุปราคาเกิดเวลากลางคืนวันเพ็ญ โลกอยู่ตรงกลางบังเงาไม่ให้แสงอาทิตย์ไปกระทบดวงจันทร์', 'สุริยุปราคา = จันทร์อยู่กลาง / จันทรุปราคา = โลกอยู่กลาง', 'จันทรุปราคา = โลกอยู่กลาง กลางคืน วันเพ็ญ', '["ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_051', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'การสังเคราะห์ด้วยแสงและพืชศาสตร์', 'ในกระบวนการสังเคราะห์ด้วยแสงของพืช สารตั้งต้นและผลผลิตหลักที่ได้คือข้อใด (ข้อที่ 51)', '["สารตั้งต้น: น้ำ + แก๊สคาร์บอนไดออกไซด์ / ผลผลิต: น้ำตาลกลูโคส + แก๊สออกซิเจน","สารตั้งต้น: แก๊สออกซิเจน + แป้ง / ผลผลิต: น้ำ + แก๊สคาร์บอนไดออกไซด์","สารตั้งต้น: น้ำตาลกลูโคส + น้ำ / ผลผลิต: คลอโรฟิลล์","สารตั้งต้น: ปุ๋ยไนโตรเจน / ผลผลิต: แก๊สคาร์บอนไดออกไซด์"]', 0, 'พืชใช้แสง น้ำ และ CO2 สังเคราะห์น้ำตาลกลูโคสและปล่อย O2 ออกมา', 'อย่าสับสนกับการหายใจของพืชที่ดูด O2 แล้วปล่อย CO2', 'สังเคราะห์แสง = ดูด CO2 ปล่อย O2', '["การสังเคราะห์ด้วยแสงและพืชศาสตร์","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_052', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'ระบบหมุนเวียนเลือดและหัวใจ', 'เส้นเลือดชนิดใดที่นำเลือดที่มีแก๊สออกซิเจนสูงจากปอดกลับเข้าสู่หัวใจห้องบนซ้าย (ข้อที่ 52)', '["พัลโมนารีเวน (Pulmonary Vein)","พัลโมนารีอาร์เตอรี (Pulmonary Artery)","เอออร์ตา (Aorta)","เวนาคาวา (Vena Cava)"]', 0, 'พัลโมนารีเวนเป็นเส้นเลือดเวนเส้นเดียวที่ลำเลียงเลือดแดงมีออกซิเจนสูงจากปอดสู่หัวใจ', 'ปกติเส้นเลือดเวนจะมีเลือดดำ แต่พัลโมนารีเวนเป็นข้อยกเว้น', 'จากปอดเข้าหัวใจ = พัลโมนารีเวน (เลือดแดง)', '["ระบบหมุนเวียนเลือดและหัวใจ","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_053', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'ระบบย่อยอาหารและสารอาหาร', 'เอนไซม์ ''เปปซิน'' ในกระเพาะอาหารของมนุษย์ ทำหน้าที่ย่อยสารอาหารประเภทใดและทำงานได้ดีในสภาวะใด (ข้อที่ 53)', '["ย่อยโปรตีน ในสภาวะที่เป็นกรด (กรดไฮโดรคลอริก)","ย่อยไขมัน ในสภาวะที่เป็นเบส","ย่อยแป้ง ในสภาวะที่เป็นกลาง","ย่อยวิตามิน ในสภาวะที่เป็นกรด"]', 0, 'กระเพาะอาหารหลั่งกรดไฮโดรคลอริกเพื่อให้เอนไซม์เปปซินย่อยโปรตีนได้อย่างมีประสิทธิภาพ', 'เอนไซม์ในกระเพาะชอบกรด ส่วนในลำไส้เล็กชอบเบส', 'กระเพาะ = กรด + ย่อยโปรตีน', '["ระบบย่อยอาหารและสารอาหาร","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_054', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'โซ่อาหารและกฎ 10% พลังงาน', 'สิ่งมีชีวิตใดในระบบนิเวศที่มีบทบาทสำคัญในการเปลี่ยนอินทรียสารให้กลับคืนเป็นแร่ธาตุในดิน (ข้อที่ 54)', '["ผู้ย่อยสลายสารอินทรีย์ (Decomposers) เช่น เห็ด รา แบคทีเรีย","ผู้ผลิต (Producers) เช่น สาหร่ายและพืชสีเขียว","ผู้บริโภคซากสัตว์ (Scavengers) เช่น แร้ง","ผู้บริโภคลำดับสูงสุด"]', 0, 'เห็ด รา และแบคทีเรีย ย่อยสลายซากพืชซากสัตว์คืนธาตุอาหารลงสู่ดินและวัฏจักร', 'สัตว์กินซาก เช่น แร้ง เป็นผู้บริโภค ไม่ใช่ผู้ย่อยสลายอินทรียสารระดับโมเลกุล', 'ย่อยสลายคืนสู่ดิน = เห็ด รา แบคทีเรีย', '["โซ่อาหารและกฎ 10% พลังงาน","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_055', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'แรงพยุงและความหนาแน่น', 'วัตถุก้อนหนึ่งมีมวล 80 กรัม ปริมาตร 100 ลูกบาศก์เซนติเมตร เมื่อนำไปลอยในน้ำบริสุทธิ์จะมีสภาพเป็นอย่างไร (ข้อที่ 55)', '["ลอยน้ำ โดยมีปริมาตรจมน้ำ 80% และโผล่พ้นน้ำ 20%","จมลงสู่ก้นภาชนะทันที","ลอยน้ำ โดยมีปริมาตรจมน้ำ 20% และโผล่พ้นน้ำ 80%","ลอยปริ่มน้ำพอดี 100%"]', 0, 'ความหนาแน่นวัตถุ = 80/100 = 0.8 g/cm³ น้อยกว่าน้ำ (1.0) จึงลอย และมีสัดส่วนจม 80%', 'ความหนาแน่นวัตถุคือเปอร์เซ็นต์ส่วนที่จมน้ำ', 'ความหนาแน่น = สัดส่วนปริมาตรที่จมน้ำ', '["แรงพยุงและความหนาแน่น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_056', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'วงจรไฟฟ้าและกฎของโอห์ม', 'เมื่อนำหลอดไฟ 3 หลอดมาต่อกันแบบ ''ขนาน'' หากหลอดไฟดวงหนึ่งขาด หลอดไฟที่เหลือจะเป็นอย่างไร (ข้อที่ 56)', '["หลอดไฟที่เหลือยังคงสว่างตามปกติ","หลอดไฟที่เหลือจะดับทั้งหมดทันที","หลอดไฟที่เหลือจะสว่างลดลงครึ่งหนึ่ง","หลอดไฟที่เหลือจะระเบิด"]', 0, 'การต่อแบบขนาน กระแสไฟฟ้ามีทางเดินแยกกันเป็นอิสระ เมื่อหลอดหนึ่งขาด วงจรอื่นยังคงครบวงจร', 'ถ้าต่อแบบอนุกรม หลอดหนึ่งขาดจะดับทั้งหมด', 'ต่อขนาน = วงจรบ้าน = ดับ 1 ดวง ดวงอื่นยังสว่าง', '["วงจรไฟฟ้าและกฎของโอห์ม","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_057', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'แสง เลนส์ และการมองเห็น', 'ปรากฏการณ์ ''รุ้งกินน้ำ'' เกิดจากแสงอาทิตย์กระทบกับละอองน้ำในอากาศผ่านกระบวนการใดตามลำดับ (ข้อที่ 57)', '["การหักเห -> การสะท้อนกลับหมด -> การกระจายของแสง","การแทรกสอด -> การเลี้ยวเบน -> การดูดกลืน","การสะท้อนปกติ -> การรวมแสง","การแผ่รังสี -> การพาความร้อน"]', 0, 'แสงแดดส่องเข้าละอองน้ำ หักเหและกระจายแสงสี แล้วสะท้อนกลับหมดภายในหยดน้ำออกมาสู่สายตา', 'รุ้งกินน้ำจะเกิดทิศตรงข้ามกับดวงอาทิตย์เสมอ', 'รุ้งกินน้ำ = หักเห + กระจายแสง + สะท้อนกลับหมด', '["แสง เลนส์ และการมองเห็น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_058', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'การแยกสารและโครมาโทกราฟี', 'วิธีใดเหมาะสมที่สุดในการแยก ''เกลือแกง'' ออกจาก ''น้ำทะเล'' (ข้อที่ 58)', '["การระเหยแห้ง (Evaporation)","การกรองด้วยกระดาษกรอง","การใช้แม่เหล็กดูด","การสกัดด้วยตัวทำละลาย"]', 0, 'เกลือละลายเป็นเนื้อเดียวกับน้ำ ต้องใช้ความร้อนระเหยน้ำออกไปจนเหลือผลึกเกลือตกค้าง', 'การกรองไม่สามารถแยกสารที่ละลายเป็นเนื้อเดียวกันได้', 'น้ำเกลือระเหยแห้งได้ผลึกเกลือ', '["การแยกสารและโครมาโทกราฟี","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_059', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'ชั้นบรรยากาศและสภาพอากาศ', 'แก๊สชนิดใดมีสัดส่วนปริมาณมากที่สุดในบรรยากาศของโลก (ข้อที่ 59)', '["แก๊สไนโตรเจน (ประมาณ 78%)","แก๊สออกซิเจน (ประมาณ 21%)","แก๊สคาร์บอนไดออกไซด์ (ประมาณ 0.04%)","แก๊สฮีเลียม"]', 0, 'อากาศมีแก๊สไนโตรเจนมากที่สุด 78% รองลงมาคือออกซิเจน 21% และอาร์กอน/คาร์บอนไดออกไซด์', 'มนุษย์หายใจใช้ออกซิเจน แต่ในอากาศมีไนโตรเจนมากที่สุด', 'อากาศ = ไนโตรเจน 78% + ออกซิเจน 21%', '["ชั้นบรรยากาศและสภาพอากาศ","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_060', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา', 'ปรากฏการณ์ ''จันทรุปราคา'' จะเกิดขึ้นได้เฉพาะในวันใดและวัตถุใดอยู่ตรงกลาง (ข้อที่ 60)', '["วันขึ้น 15 ค่ำ (ดวงจันทร์เต็มดวง) โดยมี ''โลก'' อยู่ตรงกลางระหว่างดวงอาทิตย์กับดวงจันทร์","วันแรม 15 ค่ำ โดยมีดวงจันทร์อยู่ตรงกลาง","วันขึ้น 8 ค่ำ โดยมีดวงอาทิตย์อยู่ตรงกลาง","วันแรม 1 ค่ำ โดยมีดาวพุธอยู่ตรงกลาง"]', 0, 'จันทรุปราคาเกิดเวลากลางคืนวันเพ็ญ โลกอยู่ตรงกลางบังเงาไม่ให้แสงอาทิตย์ไปกระทบดวงจันทร์', 'สุริยุปราคา = จันทร์อยู่กลาง / จันทรุปราคา = โลกอยู่กลาง', 'จันทรุปราคา = โลกอยู่กลาง กลางคืน วันเพ็ญ', '["ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_061', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'การสังเคราะห์ด้วยแสงและพืชศาสตร์', 'ในกระบวนการสังเคราะห์ด้วยแสงของพืช สารตั้งต้นและผลผลิตหลักที่ได้คือข้อใด (ข้อที่ 61)', '["สารตั้งต้น: น้ำ + แก๊สคาร์บอนไดออกไซด์ / ผลผลิต: น้ำตาลกลูโคส + แก๊สออกซิเจน","สารตั้งต้น: แก๊สออกซิเจน + แป้ง / ผลผลิต: น้ำ + แก๊สคาร์บอนไดออกไซด์","สารตั้งต้น: น้ำตาลกลูโคส + น้ำ / ผลผลิต: คลอโรฟิลล์","สารตั้งต้น: ปุ๋ยไนโตรเจน / ผลผลิต: แก๊สคาร์บอนไดออกไซด์"]', 0, 'พืชใช้แสง น้ำ และ CO2 สังเคราะห์น้ำตาลกลูโคสและปล่อย O2 ออกมา', 'อย่าสับสนกับการหายใจของพืชที่ดูด O2 แล้วปล่อย CO2', 'สังเคราะห์แสง = ดูด CO2 ปล่อย O2', '["การสังเคราะห์ด้วยแสงและพืชศาสตร์","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_062', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'ระบบหมุนเวียนเลือดและหัวใจ', 'เส้นเลือดชนิดใดที่นำเลือดที่มีแก๊สออกซิเจนสูงจากปอดกลับเข้าสู่หัวใจห้องบนซ้าย (ข้อที่ 62)', '["พัลโมนารีเวน (Pulmonary Vein)","พัลโมนารีอาร์เตอรี (Pulmonary Artery)","เอออร์ตา (Aorta)","เวนาคาวา (Vena Cava)"]', 0, 'พัลโมนารีเวนเป็นเส้นเลือดเวนเส้นเดียวที่ลำเลียงเลือดแดงมีออกซิเจนสูงจากปอดสู่หัวใจ', 'ปกติเส้นเลือดเวนจะมีเลือดดำ แต่พัลโมนารีเวนเป็นข้อยกเว้น', 'จากปอดเข้าหัวใจ = พัลโมนารีเวน (เลือดแดง)', '["ระบบหมุนเวียนเลือดและหัวใจ","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_063', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ระบบย่อยอาหารและสารอาหาร', 'เอนไซม์ ''เปปซิน'' ในกระเพาะอาหารของมนุษย์ ทำหน้าที่ย่อยสารอาหารประเภทใดและทำงานได้ดีในสภาวะใด (ข้อที่ 63)', '["ย่อยโปรตีน ในสภาวะที่เป็นกรด (กรดไฮโดรคลอริก)","ย่อยไขมัน ในสภาวะที่เป็นเบส","ย่อยแป้ง ในสภาวะที่เป็นกลาง","ย่อยวิตามิน ในสภาวะที่เป็นกรด"]', 0, 'กระเพาะอาหารหลั่งกรดไฮโดรคลอริกเพื่อให้เอนไซม์เปปซินย่อยโปรตีนได้อย่างมีประสิทธิภาพ', 'เอนไซม์ในกระเพาะชอบกรด ส่วนในลำไส้เล็กชอบเบส', 'กระเพาะ = กรด + ย่อยโปรตีน', '["ระบบย่อยอาหารและสารอาหาร","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_064', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'โซ่อาหารและกฎ 10% พลังงาน', 'สิ่งมีชีวิตใดในระบบนิเวศที่มีบทบาทสำคัญในการเปลี่ยนอินทรียสารให้กลับคืนเป็นแร่ธาตุในดิน (ข้อที่ 64)', '["ผู้ย่อยสลายสารอินทรีย์ (Decomposers) เช่น เห็ด รา แบคทีเรีย","ผู้ผลิต (Producers) เช่น สาหร่ายและพืชสีเขียว","ผู้บริโภคซากสัตว์ (Scavengers) เช่น แร้ง","ผู้บริโภคลำดับสูงสุด"]', 0, 'เห็ด รา และแบคทีเรีย ย่อยสลายซากพืชซากสัตว์คืนธาตุอาหารลงสู่ดินและวัฏจักร', 'สัตว์กินซาก เช่น แร้ง เป็นผู้บริโภค ไม่ใช่ผู้ย่อยสลายอินทรียสารระดับโมเลกุล', 'ย่อยสลายคืนสู่ดิน = เห็ด รา แบคทีเรีย', '["โซ่อาหารและกฎ 10% พลังงาน","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_065', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'แรงพยุงและความหนาแน่น', 'วัตถุก้อนหนึ่งมีมวล 80 กรัม ปริมาตร 100 ลูกบาศก์เซนติเมตร เมื่อนำไปลอยในน้ำบริสุทธิ์จะมีสภาพเป็นอย่างไร (ข้อที่ 65)', '["ลอยน้ำ โดยมีปริมาตรจมน้ำ 80% และโผล่พ้นน้ำ 20%","จมลงสู่ก้นภาชนะทันที","ลอยน้ำ โดยมีปริมาตรจมน้ำ 20% และโผล่พ้นน้ำ 80%","ลอยปริ่มน้ำพอดี 100%"]', 0, 'ความหนาแน่นวัตถุ = 80/100 = 0.8 g/cm³ น้อยกว่าน้ำ (1.0) จึงลอย และมีสัดส่วนจม 80%', 'ความหนาแน่นวัตถุคือเปอร์เซ็นต์ส่วนที่จมน้ำ', 'ความหนาแน่น = สัดส่วนปริมาตรที่จมน้ำ', '["แรงพยุงและความหนาแน่น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_066', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'วงจรไฟฟ้าและกฎของโอห์ม', 'เมื่อนำหลอดไฟ 3 หลอดมาต่อกันแบบ ''ขนาน'' หากหลอดไฟดวงหนึ่งขาด หลอดไฟที่เหลือจะเป็นอย่างไร (ข้อที่ 66)', '["หลอดไฟที่เหลือยังคงสว่างตามปกติ","หลอดไฟที่เหลือจะดับทั้งหมดทันที","หลอดไฟที่เหลือจะสว่างลดลงครึ่งหนึ่ง","หลอดไฟที่เหลือจะระเบิด"]', 0, 'การต่อแบบขนาน กระแสไฟฟ้ามีทางเดินแยกกันเป็นอิสระ เมื่อหลอดหนึ่งขาด วงจรอื่นยังคงครบวงจร', 'ถ้าต่อแบบอนุกรม หลอดหนึ่งขาดจะดับทั้งหมด', 'ต่อขนาน = วงจรบ้าน = ดับ 1 ดวง ดวงอื่นยังสว่าง', '["วงจรไฟฟ้าและกฎของโอห์ม","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_067', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'แสง เลนส์ และการมองเห็น', 'ปรากฏการณ์ ''รุ้งกินน้ำ'' เกิดจากแสงอาทิตย์กระทบกับละอองน้ำในอากาศผ่านกระบวนการใดตามลำดับ (ข้อที่ 67)', '["การหักเห -> การสะท้อนกลับหมด -> การกระจายของแสง","การแทรกสอด -> การเลี้ยวเบน -> การดูดกลืน","การสะท้อนปกติ -> การรวมแสง","การแผ่รังสี -> การพาความร้อน"]', 0, 'แสงแดดส่องเข้าละอองน้ำ หักเหและกระจายแสงสี แล้วสะท้อนกลับหมดภายในหยดน้ำออกมาสู่สายตา', 'รุ้งกินน้ำจะเกิดทิศตรงข้ามกับดวงอาทิตย์เสมอ', 'รุ้งกินน้ำ = หักเห + กระจายแสง + สะท้อนกลับหมด', '["แสง เลนส์ และการมองเห็น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_068', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'การแยกสารและโครมาโทกราฟี', 'วิธีใดเหมาะสมที่สุดในการแยก ''เกลือแกง'' ออกจาก ''น้ำทะเล'' (ข้อที่ 68)', '["การระเหยแห้ง (Evaporation)","การกรองด้วยกระดาษกรอง","การใช้แม่เหล็กดูด","การสกัดด้วยตัวทำละลาย"]', 0, 'เกลือละลายเป็นเนื้อเดียวกับน้ำ ต้องใช้ความร้อนระเหยน้ำออกไปจนเหลือผลึกเกลือตกค้าง', 'การกรองไม่สามารถแยกสารที่ละลายเป็นเนื้อเดียวกันได้', 'น้ำเกลือระเหยแห้งได้ผลึกเกลือ', '["การแยกสารและโครมาโทกราฟี","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_069', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ชั้นบรรยากาศและสภาพอากาศ', 'แก๊สชนิดใดมีสัดส่วนปริมาณมากที่สุดในบรรยากาศของโลก (ข้อที่ 69)', '["แก๊สไนโตรเจน (ประมาณ 78%)","แก๊สออกซิเจน (ประมาณ 21%)","แก๊สคาร์บอนไดออกไซด์ (ประมาณ 0.04%)","แก๊สฮีเลียม"]', 0, 'อากาศมีแก๊สไนโตรเจนมากที่สุด 78% รองลงมาคือออกซิเจน 21% และอาร์กอน/คาร์บอนไดออกไซด์', 'มนุษย์หายใจใช้ออกซิเจน แต่ในอากาศมีไนโตรเจนมากที่สุด', 'อากาศ = ไนโตรเจน 78% + ออกซิเจน 21%', '["ชั้นบรรยากาศและสภาพอากาศ","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_070', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา', 'ปรากฏการณ์ ''จันทรุปราคา'' จะเกิดขึ้นได้เฉพาะในวันใดและวัตถุใดอยู่ตรงกลาง (ข้อที่ 70)', '["วันขึ้น 15 ค่ำ (ดวงจันทร์เต็มดวง) โดยมี ''โลก'' อยู่ตรงกลางระหว่างดวงอาทิตย์กับดวงจันทร์","วันแรม 15 ค่ำ โดยมีดวงจันทร์อยู่ตรงกลาง","วันขึ้น 8 ค่ำ โดยมีดวงอาทิตย์อยู่ตรงกลาง","วันแรม 1 ค่ำ โดยมีดาวพุธอยู่ตรงกลาง"]', 0, 'จันทรุปราคาเกิดเวลากลางคืนวันเพ็ญ โลกอยู่ตรงกลางบังเงาไม่ให้แสงอาทิตย์ไปกระทบดวงจันทร์', 'สุริยุปราคา = จันทร์อยู่กลาง / จันทรุปราคา = โลกอยู่กลาง', 'จันทรุปราคา = โลกอยู่กลาง กลางคืน วันเพ็ญ', '["ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_071', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'การสังเคราะห์ด้วยแสงและพืชศาสตร์', 'ในกระบวนการสังเคราะห์ด้วยแสงของพืช สารตั้งต้นและผลผลิตหลักที่ได้คือข้อใด (ข้อที่ 71)', '["สารตั้งต้น: น้ำ + แก๊สคาร์บอนไดออกไซด์ / ผลผลิต: น้ำตาลกลูโคส + แก๊สออกซิเจน","สารตั้งต้น: แก๊สออกซิเจน + แป้ง / ผลผลิต: น้ำ + แก๊สคาร์บอนไดออกไซด์","สารตั้งต้น: น้ำตาลกลูโคส + น้ำ / ผลผลิต: คลอโรฟิลล์","สารตั้งต้น: ปุ๋ยไนโตรเจน / ผลผลิต: แก๊สคาร์บอนไดออกไซด์"]', 0, 'พืชใช้แสง น้ำ และ CO2 สังเคราะห์น้ำตาลกลูโคสและปล่อย O2 ออกมา', 'อย่าสับสนกับการหายใจของพืชที่ดูด O2 แล้วปล่อย CO2', 'สังเคราะห์แสง = ดูด CO2 ปล่อย O2', '["การสังเคราะห์ด้วยแสงและพืชศาสตร์","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_072', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'ระบบหมุนเวียนเลือดและหัวใจ', 'เส้นเลือดชนิดใดที่นำเลือดที่มีแก๊สออกซิเจนสูงจากปอดกลับเข้าสู่หัวใจห้องบนซ้าย (ข้อที่ 72)', '["พัลโมนารีเวน (Pulmonary Vein)","พัลโมนารีอาร์เตอรี (Pulmonary Artery)","เอออร์ตา (Aorta)","เวนาคาวา (Vena Cava)"]', 0, 'พัลโมนารีเวนเป็นเส้นเลือดเวนเส้นเดียวที่ลำเลียงเลือดแดงมีออกซิเจนสูงจากปอดสู่หัวใจ', 'ปกติเส้นเลือดเวนจะมีเลือดดำ แต่พัลโมนารีเวนเป็นข้อยกเว้น', 'จากปอดเข้าหัวใจ = พัลโมนารีเวน (เลือดแดง)', '["ระบบหมุนเวียนเลือดและหัวใจ","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_073', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'ระบบย่อยอาหารและสารอาหาร', 'เอนไซม์ ''เปปซิน'' ในกระเพาะอาหารของมนุษย์ ทำหน้าที่ย่อยสารอาหารประเภทใดและทำงานได้ดีในสภาวะใด (ข้อที่ 73)', '["ย่อยโปรตีน ในสภาวะที่เป็นกรด (กรดไฮโดรคลอริก)","ย่อยไขมัน ในสภาวะที่เป็นเบส","ย่อยแป้ง ในสภาวะที่เป็นกลาง","ย่อยวิตามิน ในสภาวะที่เป็นกรด"]', 0, 'กระเพาะอาหารหลั่งกรดไฮโดรคลอริกเพื่อให้เอนไซม์เปปซินย่อยโปรตีนได้อย่างมีประสิทธิภาพ', 'เอนไซม์ในกระเพาะชอบกรด ส่วนในลำไส้เล็กชอบเบส', 'กระเพาะ = กรด + ย่อยโปรตีน', '["ระบบย่อยอาหารและสารอาหาร","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_074', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'โซ่อาหารและกฎ 10% พลังงาน', 'สิ่งมีชีวิตใดในระบบนิเวศที่มีบทบาทสำคัญในการเปลี่ยนอินทรียสารให้กลับคืนเป็นแร่ธาตุในดิน (ข้อที่ 74)', '["ผู้ย่อยสลายสารอินทรีย์ (Decomposers) เช่น เห็ด รา แบคทีเรีย","ผู้ผลิต (Producers) เช่น สาหร่ายและพืชสีเขียว","ผู้บริโภคซากสัตว์ (Scavengers) เช่น แร้ง","ผู้บริโภคลำดับสูงสุด"]', 0, 'เห็ด รา และแบคทีเรีย ย่อยสลายซากพืชซากสัตว์คืนธาตุอาหารลงสู่ดินและวัฏจักร', 'สัตว์กินซาก เช่น แร้ง เป็นผู้บริโภค ไม่ใช่ผู้ย่อยสลายอินทรียสารระดับโมเลกุล', 'ย่อยสลายคืนสู่ดิน = เห็ด รา แบคทีเรีย', '["โซ่อาหารและกฎ 10% พลังงาน","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_075', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'แรงพยุงและความหนาแน่น', 'วัตถุก้อนหนึ่งมีมวล 80 กรัม ปริมาตร 100 ลูกบาศก์เซนติเมตร เมื่อนำไปลอยในน้ำบริสุทธิ์จะมีสภาพเป็นอย่างไร (ข้อที่ 75)', '["ลอยน้ำ โดยมีปริมาตรจมน้ำ 80% และโผล่พ้นน้ำ 20%","จมลงสู่ก้นภาชนะทันที","ลอยน้ำ โดยมีปริมาตรจมน้ำ 20% และโผล่พ้นน้ำ 80%","ลอยปริ่มน้ำพอดี 100%"]', 0, 'ความหนาแน่นวัตถุ = 80/100 = 0.8 g/cm³ น้อยกว่าน้ำ (1.0) จึงลอย และมีสัดส่วนจม 80%', 'ความหนาแน่นวัตถุคือเปอร์เซ็นต์ส่วนที่จมน้ำ', 'ความหนาแน่น = สัดส่วนปริมาตรที่จมน้ำ', '["แรงพยุงและความหนาแน่น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_076', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'วงจรไฟฟ้าและกฎของโอห์ม', 'เมื่อนำหลอดไฟ 3 หลอดมาต่อกันแบบ ''ขนาน'' หากหลอดไฟดวงหนึ่งขาด หลอดไฟที่เหลือจะเป็นอย่างไร (ข้อที่ 76)', '["หลอดไฟที่เหลือยังคงสว่างตามปกติ","หลอดไฟที่เหลือจะดับทั้งหมดทันที","หลอดไฟที่เหลือจะสว่างลดลงครึ่งหนึ่ง","หลอดไฟที่เหลือจะระเบิด"]', 0, 'การต่อแบบขนาน กระแสไฟฟ้ามีทางเดินแยกกันเป็นอิสระ เมื่อหลอดหนึ่งขาด วงจรอื่นยังคงครบวงจร', 'ถ้าต่อแบบอนุกรม หลอดหนึ่งขาดจะดับทั้งหมด', 'ต่อขนาน = วงจรบ้าน = ดับ 1 ดวง ดวงอื่นยังสว่าง', '["วงจรไฟฟ้าและกฎของโอห์ม","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_077', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'แสง เลนส์ และการมองเห็น', 'ปรากฏการณ์ ''รุ้งกินน้ำ'' เกิดจากแสงอาทิตย์กระทบกับละอองน้ำในอากาศผ่านกระบวนการใดตามลำดับ (ข้อที่ 77)', '["การหักเห -> การสะท้อนกลับหมด -> การกระจายของแสง","การแทรกสอด -> การเลี้ยวเบน -> การดูดกลืน","การสะท้อนปกติ -> การรวมแสง","การแผ่รังสี -> การพาความร้อน"]', 0, 'แสงแดดส่องเข้าละอองน้ำ หักเหและกระจายแสงสี แล้วสะท้อนกลับหมดภายในหยดน้ำออกมาสู่สายตา', 'รุ้งกินน้ำจะเกิดทิศตรงข้ามกับดวงอาทิตย์เสมอ', 'รุ้งกินน้ำ = หักเห + กระจายแสง + สะท้อนกลับหมด', '["แสง เลนส์ และการมองเห็น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_078', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'การแยกสารและโครมาโทกราฟี', 'วิธีใดเหมาะสมที่สุดในการแยก ''เกลือแกง'' ออกจาก ''น้ำทะเล'' (ข้อที่ 78)', '["การระเหยแห้ง (Evaporation)","การกรองด้วยกระดาษกรอง","การใช้แม่เหล็กดูด","การสกัดด้วยตัวทำละลาย"]', 0, 'เกลือละลายเป็นเนื้อเดียวกับน้ำ ต้องใช้ความร้อนระเหยน้ำออกไปจนเหลือผลึกเกลือตกค้าง', 'การกรองไม่สามารถแยกสารที่ละลายเป็นเนื้อเดียวกันได้', 'น้ำเกลือระเหยแห้งได้ผลึกเกลือ', '["การแยกสารและโครมาโทกราฟี","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_079', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'ชั้นบรรยากาศและสภาพอากาศ', 'แก๊สชนิดใดมีสัดส่วนปริมาณมากที่สุดในบรรยากาศของโลก (ข้อที่ 79)', '["แก๊สไนโตรเจน (ประมาณ 78%)","แก๊สออกซิเจน (ประมาณ 21%)","แก๊สคาร์บอนไดออกไซด์ (ประมาณ 0.04%)","แก๊สฮีเลียม"]', 0, 'อากาศมีแก๊สไนโตรเจนมากที่สุด 78% รองลงมาคือออกซิเจน 21% และอาร์กอน/คาร์บอนไดออกไซด์', 'มนุษย์หายใจใช้ออกซิเจน แต่ในอากาศมีไนโตรเจนมากที่สุด', 'อากาศ = ไนโตรเจน 78% + ออกซิเจน 21%', '["ชั้นบรรยากาศและสภาพอากาศ","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_080', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา', 'ปรากฏการณ์ ''จันทรุปราคา'' จะเกิดขึ้นได้เฉพาะในวันใดและวัตถุใดอยู่ตรงกลาง (ข้อที่ 80)', '["วันขึ้น 15 ค่ำ (ดวงจันทร์เต็มดวง) โดยมี ''โลก'' อยู่ตรงกลางระหว่างดวงอาทิตย์กับดวงจันทร์","วันแรม 15 ค่ำ โดยมีดวงจันทร์อยู่ตรงกลาง","วันขึ้น 8 ค่ำ โดยมีดวงอาทิตย์อยู่ตรงกลาง","วันแรม 1 ค่ำ โดยมีดาวพุธอยู่ตรงกลาง"]', 0, 'จันทรุปราคาเกิดเวลากลางคืนวันเพ็ญ โลกอยู่ตรงกลางบังเงาไม่ให้แสงอาทิตย์ไปกระทบดวงจันทร์', 'สุริยุปราคา = จันทร์อยู่กลาง / จันทรุปราคา = โลกอยู่กลาง', 'จันทรุปราคา = โลกอยู่กลาง กลางคืน วันเพ็ญ', '["ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_081', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'การสังเคราะห์ด้วยแสงและพืชศาสตร์', 'ในกระบวนการสังเคราะห์ด้วยแสงของพืช สารตั้งต้นและผลผลิตหลักที่ได้คือข้อใด (ข้อที่ 81)', '["สารตั้งต้น: น้ำ + แก๊สคาร์บอนไดออกไซด์ / ผลผลิต: น้ำตาลกลูโคส + แก๊สออกซิเจน","สารตั้งต้น: แก๊สออกซิเจน + แป้ง / ผลผลิต: น้ำ + แก๊สคาร์บอนไดออกไซด์","สารตั้งต้น: น้ำตาลกลูโคส + น้ำ / ผลผลิต: คลอโรฟิลล์","สารตั้งต้น: ปุ๋ยไนโตรเจน / ผลผลิต: แก๊สคาร์บอนไดออกไซด์"]', 0, 'พืชใช้แสง น้ำ และ CO2 สังเคราะห์น้ำตาลกลูโคสและปล่อย O2 ออกมา', 'อย่าสับสนกับการหายใจของพืชที่ดูด O2 แล้วปล่อย CO2', 'สังเคราะห์แสง = ดูด CO2 ปล่อย O2', '["การสังเคราะห์ด้วยแสงและพืชศาสตร์","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_082', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'ระบบหมุนเวียนเลือดและหัวใจ', 'เส้นเลือดชนิดใดที่นำเลือดที่มีแก๊สออกซิเจนสูงจากปอดกลับเข้าสู่หัวใจห้องบนซ้าย (ข้อที่ 82)', '["พัลโมนารีเวน (Pulmonary Vein)","พัลโมนารีอาร์เตอรี (Pulmonary Artery)","เอออร์ตา (Aorta)","เวนาคาวา (Vena Cava)"]', 0, 'พัลโมนารีเวนเป็นเส้นเลือดเวนเส้นเดียวที่ลำเลียงเลือดแดงมีออกซิเจนสูงจากปอดสู่หัวใจ', 'ปกติเส้นเลือดเวนจะมีเลือดดำ แต่พัลโมนารีเวนเป็นข้อยกเว้น', 'จากปอดเข้าหัวใจ = พัลโมนารีเวน (เลือดแดง)', '["ระบบหมุนเวียนเลือดและหัวใจ","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_083', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'ระบบย่อยอาหารและสารอาหาร', 'เอนไซม์ ''เปปซิน'' ในกระเพาะอาหารของมนุษย์ ทำหน้าที่ย่อยสารอาหารประเภทใดและทำงานได้ดีในสภาวะใด (ข้อที่ 83)', '["ย่อยโปรตีน ในสภาวะที่เป็นกรด (กรดไฮโดรคลอริก)","ย่อยไขมัน ในสภาวะที่เป็นเบส","ย่อยแป้ง ในสภาวะที่เป็นกลาง","ย่อยวิตามิน ในสภาวะที่เป็นกรด"]', 0, 'กระเพาะอาหารหลั่งกรดไฮโดรคลอริกเพื่อให้เอนไซม์เปปซินย่อยโปรตีนได้อย่างมีประสิทธิภาพ', 'เอนไซม์ในกระเพาะชอบกรด ส่วนในลำไส้เล็กชอบเบส', 'กระเพาะ = กรด + ย่อยโปรตีน', '["ระบบย่อยอาหารและสารอาหาร","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_084', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'โซ่อาหารและกฎ 10% พลังงาน', 'สิ่งมีชีวิตใดในระบบนิเวศที่มีบทบาทสำคัญในการเปลี่ยนอินทรียสารให้กลับคืนเป็นแร่ธาตุในดิน (ข้อที่ 84)', '["ผู้ย่อยสลายสารอินทรีย์ (Decomposers) เช่น เห็ด รา แบคทีเรีย","ผู้ผลิต (Producers) เช่น สาหร่ายและพืชสีเขียว","ผู้บริโภคซากสัตว์ (Scavengers) เช่น แร้ง","ผู้บริโภคลำดับสูงสุด"]', 0, 'เห็ด รา และแบคทีเรีย ย่อยสลายซากพืชซากสัตว์คืนธาตุอาหารลงสู่ดินและวัฏจักร', 'สัตว์กินซาก เช่น แร้ง เป็นผู้บริโภค ไม่ใช่ผู้ย่อยสลายอินทรียสารระดับโมเลกุล', 'ย่อยสลายคืนสู่ดิน = เห็ด รา แบคทีเรีย', '["โซ่อาหารและกฎ 10% พลังงาน","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_085', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'แรงพยุงและความหนาแน่น', 'วัตถุก้อนหนึ่งมีมวล 80 กรัม ปริมาตร 100 ลูกบาศก์เซนติเมตร เมื่อนำไปลอยในน้ำบริสุทธิ์จะมีสภาพเป็นอย่างไร (ข้อที่ 85)', '["ลอยน้ำ โดยมีปริมาตรจมน้ำ 80% และโผล่พ้นน้ำ 20%","จมลงสู่ก้นภาชนะทันที","ลอยน้ำ โดยมีปริมาตรจมน้ำ 20% และโผล่พ้นน้ำ 80%","ลอยปริ่มน้ำพอดี 100%"]', 0, 'ความหนาแน่นวัตถุ = 80/100 = 0.8 g/cm³ น้อยกว่าน้ำ (1.0) จึงลอย และมีสัดส่วนจม 80%', 'ความหนาแน่นวัตถุคือเปอร์เซ็นต์ส่วนที่จมน้ำ', 'ความหนาแน่น = สัดส่วนปริมาตรที่จมน้ำ', '["แรงพยุงและความหนาแน่น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_086', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'วงจรไฟฟ้าและกฎของโอห์ม', 'เมื่อนำหลอดไฟ 3 หลอดมาต่อกันแบบ ''ขนาน'' หากหลอดไฟดวงหนึ่งขาด หลอดไฟที่เหลือจะเป็นอย่างไร (ข้อที่ 86)', '["หลอดไฟที่เหลือยังคงสว่างตามปกติ","หลอดไฟที่เหลือจะดับทั้งหมดทันที","หลอดไฟที่เหลือจะสว่างลดลงครึ่งหนึ่ง","หลอดไฟที่เหลือจะระเบิด"]', 0, 'การต่อแบบขนาน กระแสไฟฟ้ามีทางเดินแยกกันเป็นอิสระ เมื่อหลอดหนึ่งขาด วงจรอื่นยังคงครบวงจร', 'ถ้าต่อแบบอนุกรม หลอดหนึ่งขาดจะดับทั้งหมด', 'ต่อขนาน = วงจรบ้าน = ดับ 1 ดวง ดวงอื่นยังสว่าง', '["วงจรไฟฟ้าและกฎของโอห์ม","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_087', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'แสง เลนส์ และการมองเห็น', 'ปรากฏการณ์ ''รุ้งกินน้ำ'' เกิดจากแสงอาทิตย์กระทบกับละอองน้ำในอากาศผ่านกระบวนการใดตามลำดับ (ข้อที่ 87)', '["การหักเห -> การสะท้อนกลับหมด -> การกระจายของแสง","การแทรกสอด -> การเลี้ยวเบน -> การดูดกลืน","การสะท้อนปกติ -> การรวมแสง","การแผ่รังสี -> การพาความร้อน"]', 0, 'แสงแดดส่องเข้าละอองน้ำ หักเหและกระจายแสงสี แล้วสะท้อนกลับหมดภายในหยดน้ำออกมาสู่สายตา', 'รุ้งกินน้ำจะเกิดทิศตรงข้ามกับดวงอาทิตย์เสมอ', 'รุ้งกินน้ำ = หักเห + กระจายแสง + สะท้อนกลับหมด', '["แสง เลนส์ และการมองเห็น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_088', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'การแยกสารและโครมาโทกราฟี', 'วิธีใดเหมาะสมที่สุดในการแยก ''เกลือแกง'' ออกจาก ''น้ำทะเล'' (ข้อที่ 88)', '["การระเหยแห้ง (Evaporation)","การกรองด้วยกระดาษกรอง","การใช้แม่เหล็กดูด","การสกัดด้วยตัวทำละลาย"]', 0, 'เกลือละลายเป็นเนื้อเดียวกับน้ำ ต้องใช้ความร้อนระเหยน้ำออกไปจนเหลือผลึกเกลือตกค้าง', 'การกรองไม่สามารถแยกสารที่ละลายเป็นเนื้อเดียวกันได้', 'น้ำเกลือระเหยแห้งได้ผลึกเกลือ', '["การแยกสารและโครมาโทกราฟี","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_089', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'ชั้นบรรยากาศและสภาพอากาศ', 'แก๊สชนิดใดมีสัดส่วนปริมาณมากที่สุดในบรรยากาศของโลก (ข้อที่ 89)', '["แก๊สไนโตรเจน (ประมาณ 78%)","แก๊สออกซิเจน (ประมาณ 21%)","แก๊สคาร์บอนไดออกไซด์ (ประมาณ 0.04%)","แก๊สฮีเลียม"]', 0, 'อากาศมีแก๊สไนโตรเจนมากที่สุด 78% รองลงมาคือออกซิเจน 21% และอาร์กอน/คาร์บอนไดออกไซด์', 'มนุษย์หายใจใช้ออกซิเจน แต่ในอากาศมีไนโตรเจนมากที่สุด', 'อากาศ = ไนโตรเจน 78% + ออกซิเจน 21%', '["ชั้นบรรยากาศและสภาพอากาศ","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_090', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา', 'ปรากฏการณ์ ''จันทรุปราคา'' จะเกิดขึ้นได้เฉพาะในวันใดและวัตถุใดอยู่ตรงกลาง (ข้อที่ 90)', '["วันขึ้น 15 ค่ำ (ดวงจันทร์เต็มดวง) โดยมี ''โลก'' อยู่ตรงกลางระหว่างดวงอาทิตย์กับดวงจันทร์","วันแรม 15 ค่ำ โดยมีดวงจันทร์อยู่ตรงกลาง","วันขึ้น 8 ค่ำ โดยมีดวงอาทิตย์อยู่ตรงกลาง","วันแรม 1 ค่ำ โดยมีดาวพุธอยู่ตรงกลาง"]', 0, 'จันทรุปราคาเกิดเวลากลางคืนวันเพ็ญ โลกอยู่ตรงกลางบังเงาไม่ให้แสงอาทิตย์ไปกระทบดวงจันทร์', 'สุริยุปราคา = จันทร์อยู่กลาง / จันทรุปราคา = โลกอยู่กลาง', 'จันทรุปราคา = โลกอยู่กลาง กลางคืน วันเพ็ญ', '["ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_091', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'การสังเคราะห์ด้วยแสงและพืชศาสตร์', 'ในกระบวนการสังเคราะห์ด้วยแสงของพืช สารตั้งต้นและผลผลิตหลักที่ได้คือข้อใด (ข้อที่ 91)', '["สารตั้งต้น: น้ำ + แก๊สคาร์บอนไดออกไซด์ / ผลผลิต: น้ำตาลกลูโคส + แก๊สออกซิเจน","สารตั้งต้น: แก๊สออกซิเจน + แป้ง / ผลผลิต: น้ำ + แก๊สคาร์บอนไดออกไซด์","สารตั้งต้น: น้ำตาลกลูโคส + น้ำ / ผลผลิต: คลอโรฟิลล์","สารตั้งต้น: ปุ๋ยไนโตรเจน / ผลผลิต: แก๊สคาร์บอนไดออกไซด์"]', 0, 'พืชใช้แสง น้ำ และ CO2 สังเคราะห์น้ำตาลกลูโคสและปล่อย O2 ออกมา', 'อย่าสับสนกับการหายใจของพืชที่ดูด O2 แล้วปล่อย CO2', 'สังเคราะห์แสง = ดูด CO2 ปล่อย O2', '["การสังเคราะห์ด้วยแสงและพืชศาสตร์","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_092', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'ระบบหมุนเวียนเลือดและหัวใจ', 'เส้นเลือดชนิดใดที่นำเลือดที่มีแก๊สออกซิเจนสูงจากปอดกลับเข้าสู่หัวใจห้องบนซ้าย (ข้อที่ 92)', '["พัลโมนารีเวน (Pulmonary Vein)","พัลโมนารีอาร์เตอรี (Pulmonary Artery)","เอออร์ตา (Aorta)","เวนาคาวา (Vena Cava)"]', 0, 'พัลโมนารีเวนเป็นเส้นเลือดเวนเส้นเดียวที่ลำเลียงเลือดแดงมีออกซิเจนสูงจากปอดสู่หัวใจ', 'ปกติเส้นเลือดเวนจะมีเลือดดำ แต่พัลโมนารีเวนเป็นข้อยกเว้น', 'จากปอดเข้าหัวใจ = พัลโมนารีเวน (เลือดแดง)', '["ระบบหมุนเวียนเลือดและหัวใจ","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_093', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ระบบย่อยอาหารและสารอาหาร', 'เอนไซม์ ''เปปซิน'' ในกระเพาะอาหารของมนุษย์ ทำหน้าที่ย่อยสารอาหารประเภทใดและทำงานได้ดีในสภาวะใด (ข้อที่ 93)', '["ย่อยโปรตีน ในสภาวะที่เป็นกรด (กรดไฮโดรคลอริก)","ย่อยไขมัน ในสภาวะที่เป็นเบส","ย่อยแป้ง ในสภาวะที่เป็นกลาง","ย่อยวิตามิน ในสภาวะที่เป็นกรด"]', 0, 'กระเพาะอาหารหลั่งกรดไฮโดรคลอริกเพื่อให้เอนไซม์เปปซินย่อยโปรตีนได้อย่างมีประสิทธิภาพ', 'เอนไซม์ในกระเพาะชอบกรด ส่วนในลำไส้เล็กชอบเบส', 'กระเพาะ = กรด + ย่อยโปรตีน', '["ระบบย่อยอาหารและสารอาหาร","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_094', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'โซ่อาหารและกฎ 10% พลังงาน', 'สิ่งมีชีวิตใดในระบบนิเวศที่มีบทบาทสำคัญในการเปลี่ยนอินทรียสารให้กลับคืนเป็นแร่ธาตุในดิน (ข้อที่ 94)', '["ผู้ย่อยสลายสารอินทรีย์ (Decomposers) เช่น เห็ด รา แบคทีเรีย","ผู้ผลิต (Producers) เช่น สาหร่ายและพืชสีเขียว","ผู้บริโภคซากสัตว์ (Scavengers) เช่น แร้ง","ผู้บริโภคลำดับสูงสุด"]', 0, 'เห็ด รา และแบคทีเรีย ย่อยสลายซากพืชซากสัตว์คืนธาตุอาหารลงสู่ดินและวัฏจักร', 'สัตว์กินซาก เช่น แร้ง เป็นผู้บริโภค ไม่ใช่ผู้ย่อยสลายอินทรียสารระดับโมเลกุล', 'ย่อยสลายคืนสู่ดิน = เห็ด รา แบคทีเรีย', '["โซ่อาหารและกฎ 10% พลังงาน","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_095', 'science', 'วิทยาศาสตร์', 'Gifted', 2, 'แรงพยุงและความหนาแน่น', 'วัตถุก้อนหนึ่งมีมวล 80 กรัม ปริมาตร 100 ลูกบาศก์เซนติเมตร เมื่อนำไปลอยในน้ำบริสุทธิ์จะมีสภาพเป็นอย่างไร (ข้อที่ 95)', '["ลอยน้ำ โดยมีปริมาตรจมน้ำ 80% และโผล่พ้นน้ำ 20%","จมลงสู่ก้นภาชนะทันที","ลอยน้ำ โดยมีปริมาตรจมน้ำ 20% และโผล่พ้นน้ำ 80%","ลอยปริ่มน้ำพอดี 100%"]', 0, 'ความหนาแน่นวัตถุ = 80/100 = 0.8 g/cm³ น้อยกว่าน้ำ (1.0) จึงลอย และมีสัดส่วนจม 80%', 'ความหนาแน่นวัตถุคือเปอร์เซ็นต์ส่วนที่จมน้ำ', 'ความหนาแน่น = สัดส่วนปริมาตรที่จมน้ำ', '["แรงพยุงและความหนาแน่น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_096', 'science', 'วิทยาศาสตร์', 'Regular', 3, 'วงจรไฟฟ้าและกฎของโอห์ม', 'เมื่อนำหลอดไฟ 3 หลอดมาต่อกันแบบ ''ขนาน'' หากหลอดไฟดวงหนึ่งขาด หลอดไฟที่เหลือจะเป็นอย่างไร (ข้อที่ 96)', '["หลอดไฟที่เหลือยังคงสว่างตามปกติ","หลอดไฟที่เหลือจะดับทั้งหมดทันที","หลอดไฟที่เหลือจะสว่างลดลงครึ่งหนึ่ง","หลอดไฟที่เหลือจะระเบิด"]', 0, 'การต่อแบบขนาน กระแสไฟฟ้ามีทางเดินแยกกันเป็นอิสระ เมื่อหลอดหนึ่งขาด วงจรอื่นยังคงครบวงจร', 'ถ้าต่อแบบอนุกรม หลอดหนึ่งขาดจะดับทั้งหมด', 'ต่อขนาน = วงจรบ้าน = ดับ 1 ดวง ดวงอื่นยังสว่าง', '["วงจรไฟฟ้าและกฎของโอห์ม","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_097', 'science', 'วิทยาศาสตร์', 'Gifted', 1, 'แสง เลนส์ และการมองเห็น', 'ปรากฏการณ์ ''รุ้งกินน้ำ'' เกิดจากแสงอาทิตย์กระทบกับละอองน้ำในอากาศผ่านกระบวนการใดตามลำดับ (ข้อที่ 97)', '["การหักเห -> การสะท้อนกลับหมด -> การกระจายของแสง","การแทรกสอด -> การเลี้ยวเบน -> การดูดกลืน","การสะท้อนปกติ -> การรวมแสง","การแผ่รังสี -> การพาความร้อน"]', 0, 'แสงแดดส่องเข้าละอองน้ำ หักเหและกระจายแสงสี แล้วสะท้อนกลับหมดภายในหยดน้ำออกมาสู่สายตา', 'รุ้งกินน้ำจะเกิดทิศตรงข้ามกับดวงอาทิตย์เสมอ', 'รุ้งกินน้ำ = หักเห + กระจายแสง + สะท้อนกลับหมด', '["แสง เลนส์ และการมองเห็น","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_098', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'การแยกสารและโครมาโทกราฟี', 'วิธีใดเหมาะสมที่สุดในการแยก ''เกลือแกง'' ออกจาก ''น้ำทะเล'' (ข้อที่ 98)', '["การระเหยแห้ง (Evaporation)","การกรองด้วยกระดาษกรอง","การใช้แม่เหล็กดูด","การสกัดด้วยตัวทำละลาย"]', 0, 'เกลือละลายเป็นเนื้อเดียวกับน้ำ ต้องใช้ความร้อนระเหยน้ำออกไปจนเหลือผลึกเกลือตกค้าง', 'การกรองไม่สามารถแยกสารที่ละลายเป็นเนื้อเดียวกันได้', 'น้ำเกลือระเหยแห้งได้ผลึกเกลือ', '["การแยกสารและโครมาโทกราฟี","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_099', 'science', 'วิทยาศาสตร์', 'Gifted', 3, 'ชั้นบรรยากาศและสภาพอากาศ', 'แก๊สชนิดใดมีสัดส่วนปริมาณมากที่สุดในบรรยากาศของโลก (ข้อที่ 99)', '["แก๊สไนโตรเจน (ประมาณ 78%)","แก๊สออกซิเจน (ประมาณ 21%)","แก๊สคาร์บอนไดออกไซด์ (ประมาณ 0.04%)","แก๊สฮีเลียม"]', 0, 'อากาศมีแก๊สไนโตรเจนมากที่สุด 78% รองลงมาคือออกซิเจน 21% และอาร์กอน/คาร์บอนไดออกไซด์', 'มนุษย์หายใจใช้ออกซิเจน แต่ในอากาศมีไนโตรเจนมากที่สุด', 'อากาศ = ไนโตรเจน 78% + ออกซิเจน 21%', '["ชั้นบรรยากาศและสภาพอากาศ","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('s_100', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา', 'ปรากฏการณ์ ''จันทรุปราคา'' จะเกิดขึ้นได้เฉพาะในวันใดและวัตถุใดอยู่ตรงกลาง (ข้อที่ 100)', '["วันขึ้น 15 ค่ำ (ดวงจันทร์เต็มดวง) โดยมี ''โลก'' อยู่ตรงกลางระหว่างดวงอาทิตย์กับดวงจันทร์","วันแรม 15 ค่ำ โดยมีดวงจันทร์อยู่ตรงกลาง","วันขึ้น 8 ค่ำ โดยมีดวงอาทิตย์อยู่ตรงกลาง","วันแรม 1 ค่ำ โดยมีดาวพุธอยู่ตรงกลาง"]', 0, 'จันทรุปราคาเกิดเวลากลางคืนวันเพ็ญ โลกอยู่ตรงกลางบังเงาไม่ให้แสงอาทิตย์ไปกระทบดวงจันทร์', 'สุริยุปราคา = จันทร์อยู่กลาง / จันทรุปราคา = โลกอยู่กลาง', 'จันทรุปราคา = โลกอยู่กลาง กลางคืน วันเพ็ญ', '["ดาราศาสตร์ น้ำขึ้น-น้ำลง และอุปราคา","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_001', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'If-Clauses (Conditional Sentences)', 'If it ______ tomorrow, we will stay at home and play board games. (Item 1)', '["rains","rain","rained","will rain"]', 0, 'First Conditional: If + Present Simple (rains), will + V.inf', 'ห้ามใช้ will ใน If-clause', 'If + V1 คู่กับ will + V.inf', '["If-Clauses (Conditional Sentences)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_002', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Subject-Verb Agreement', 'The group of students ______ working hard on their science project right now. (Item 2)', '["is","are","were","have been"]', 0, 'ประธานแท้คือ ''The group'' (เอกพจน์) กริยาจึงใช้ ''is''', 'อย่าดูคำว่า students ที่อยู่หลัง of', 'The group of / A pack of = กริยาเอกพจน์', '["Subject-Verb Agreement","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_003', 'english', 'ภาษาอังกฤษ', 'Gifted', 3, 'Past Continuous & Past Simple', 'While Tom ______ his homework, the lights suddenly went out. (Item 3)', '["was doing","did","does","is doing"]', 0, 'While + Past Continuous (was doing) แสดงเหตุการณ์ที่กำลังดำเนินอยู่', 'เหตุการณ์ที่กำลังเกิดใช้ was/were + V.ing', 'While + was/were + V.ing', '["Past Continuous & Past Simple","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_004', 'english', 'ภาษาอังกฤษ', 'Regular', 1, 'Question Tags', 'She has never been to London before, ______? (Item 4)', '["has she","hasn''t she","is she","does she"]', 0, 'คำว่า ''never'' มีความหมายปฏิเสธ Question Tag จึงต้องเป็นบอกเล่า (has she)', 'never, rarely, seldom ถือเป็นปฏิเสธ', 'ประโยคปฏิเสธ -> Tag เป็นบอกเล่า', '["Question Tags","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_005', 'english', 'ภาษาอังกฤษ', 'Gifted', 2, 'Passive Voice', 'This famous bridge ______ over 100 years ago. (Item 5)', '["was built","built","has built","is building"]', 0, 'สะพานถูกสร้างในอดีต (Passive Voice): was/were + V3 -> was built', 'สะพานสร้างตัวเองไม่ได้ ต้องใช้รูปถูกกระทำ', 'สิ่งของ + ถูกกระทำ = was/were + V.3', '["Passive Voice","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_006', 'english', 'ภาษาอังกฤษ', 'Regular', 3, 'Relative Pronouns', 'The doctor ______ helped the injured child received an award. (Item 6)', '["who","which","whom","whose"]', 0, 'ใช้ ''who'' ขยายคำนามคน (The doctor) ที่ทำหน้าที่เป็นประธาน', 'which ใช้กับสัตว์/สิ่งของ', 'คนเป็นประธาน = who', '["Relative Pronouns","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_007', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'Prepositions of Place & Time', 'The final exam will start ______ 8:30 AM on Monday morning. (Item 7)', '["at","in","on","by"]', 0, 'บอกเวลาเฉพาะเจาะจงของนาฬิกา ใช้บุพบท ''at'' (at 8:30 AM)', 'in ใช้กับเดือน/ปี, on ใช้กับวัน/วันที่, at ใช้กับเวลา', 'เวลาเจาะจง = at เสมอ', '["Prepositions of Place & Time","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_008', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Causative Verbs', 'The strict teacher let us ______ our dictionaries during the vocabulary test. (Item 8)', '["use","to use","using","used"]', 0, 'let + someone + V.inf (กริยาไม่ผัน ไม่มี to)', 'ห้ามใส่ to หลัง let/make', 'let / make + คน + V.inf (ห้ามมี to)', '["Causative Verbs","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_009', 'english', 'ภาษาอังกฤษ', 'Gifted', 3, 'Comparatives & Superlatives', 'Jupiter is ______ planet in our solar system. (Item 9)', '["the largest","larger","largest","the most large"]', 0, 'ขั้นสุดของคำพยางค์เดียวคือ the + adj-est -> the largest', 'ขั้นสุดต้องมี the เสมอ', 'ขั้นสุด = the + est', '["Comparatives & Superlatives","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_010', 'english', 'ภาษาอังกฤษ', 'Regular', 1, 'Present Perfect Tense', 'I have known my best friend ______ five years. (Item 10)', '["for","since","during","at"]', 0, 'ใช้ ''for'' นำหน้าจำนวนช่วงเวลา (for five years)', 'since ใช้กับจุดเริ่มต้นของเวลา เช่น since 2020', 'for + จำนวนเวลา / since + จุดเริ่มต้น', '["Present Perfect Tense","Regular"]');
