INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_025', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'Passive Voice', 'This famous bridge ______ over 100 years ago. (Item 25)', '["was built","built","has built","is building"]', 0, 'สะพานถูกสร้างในอดีต (Passive Voice): was/were + V3 -> was built', 'สะพานสร้างตัวเองไม่ได้ ต้องใช้รูปถูกกระทำ', 'สิ่งของ + ถูกกระทำ = was/were + V.3', '["Passive Voice","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_026', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Relative Pronouns', 'The doctor ______ helped the injured child received an award. (Item 26)', '["who","which","whom","whose"]', 0, 'ใช้ ''who'' ขยายคำนามคน (The doctor) ที่ทำหน้าที่เป็นประธาน', 'which ใช้กับสัตว์/สิ่งของ', 'คนเป็นประธาน = who', '["Relative Pronouns","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_027', 'english', 'ภาษาอังกฤษ', 'Gifted', 3, 'Prepositions of Place & Time', 'The final exam will start ______ 8:30 AM on Monday morning. (Item 27)', '["at","in","on","by"]', 0, 'บอกเวลาเฉพาะเจาะจงของนาฬิกา ใช้บุพบท ''at'' (at 8:30 AM)', 'in ใช้กับเดือน/ปี, on ใช้กับวัน/วันที่, at ใช้กับเวลา', 'เวลาเจาะจง = at เสมอ', '["Prepositions of Place & Time","Gifted"]');
