INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_059', 'english', 'ภาษาอังกฤษ', 'Gifted', 2, 'Comparatives & Superlatives', 'Jupiter is ______ planet in our solar system. (Item 59)', '["the largest","larger","largest","the most large"]', 0, 'ขั้นสุดของคำพยางค์เดียวคือ the + adj-est -> the largest', 'ขั้นสุดต้องมี the เสมอ', 'ขั้นสุด = the + est', '["Comparatives & Superlatives","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_060', 'english', 'ภาษาอังกฤษ', 'Regular', 3, 'Present Perfect Tense', 'I have known my best friend ______ five years. (Item 60)', '["for","since","during","at"]', 0, 'ใช้ ''for'' นำหน้าจำนวนช่วงเวลา (for five years)', 'since ใช้กับจุดเริ่มต้นของเวลา เช่น since 2020', 'for + จำนวนเวลา / since + จุดเริ่มต้น', '["Present Perfect Tense","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_061', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'If-Clauses (Conditional Sentences)', 'If it ______ tomorrow, we will stay at home and play board games. (Item 61)', '["rains","rain","rained","will rain"]', 0, 'First Conditional: If + Present Simple (rains), will + V.inf', 'ห้ามใช้ will ใน If-clause', 'If + V1 คู่กับ will + V.inf', '["If-Clauses (Conditional Sentences)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_062', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Subject-Verb Agreement', 'The group of students ______ working hard on their science project right now. (Item 62)', '["is","are","were","have been"]', 0, 'ประธานแท้คือ ''The group'' (เอกพจน์) กริยาจึงใช้ ''is''', 'อย่าดูคำว่า students ที่อยู่หลัง of', 'The group of / A pack of = กริยาเอกพจน์', '["Subject-Verb Agreement","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_063', 'english', 'ภาษาอังกฤษ', 'Gifted', 3, 'Past Continuous & Past Simple', 'While Tom ______ his homework, the lights suddenly went out. (Item 63)', '["was doing","did","does","is doing"]', 0, 'While + Past Continuous (was doing) แสดงเหตุการณ์ที่กำลังดำเนินอยู่', 'เหตุการณ์ที่กำลังเกิดใช้ was/were + V.ing', 'While + was/were + V.ing', '["Past Continuous & Past Simple","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_064', 'english', 'ภาษาอังกฤษ', 'Regular', 1, 'Question Tags', 'She has never been to London before, ______? (Item 64)', '["has she","hasn''t she","is she","does she"]', 0, 'คำว่า ''never'' มีความหมายปฏิเสธ Question Tag จึงต้องเป็นบอกเล่า (has she)', 'never, rarely, seldom ถือเป็นปฏิเสธ', 'ประโยคปฏิเสธ -> Tag เป็นบอกเล่า', '["Question Tags","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_065', 'english', 'ภาษาอังกฤษ', 'Gifted', 2, 'Passive Voice', 'This famous bridge ______ over 100 years ago. (Item 65)', '["was built","built","has built","is building"]', 0, 'สะพานถูกสร้างในอดีต (Passive Voice): was/were + V3 -> was built', 'สะพานสร้างตัวเองไม่ได้ ต้องใช้รูปถูกกระทำ', 'สิ่งของ + ถูกกระทำ = was/were + V.3', '["Passive Voice","Gifted"]');
