INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_093', 'english', 'ภาษาอังกฤษ', 'Gifted', 3, 'Past Continuous & Past Simple', 'While Tom ______ his homework, the lights suddenly went out. (Item 93)', '["was doing","did","does","is doing"]', 0, 'While + Past Continuous (was doing) แสดงเหตุการณ์ที่กำลังดำเนินอยู่', 'เหตุการณ์ที่กำลังเกิดใช้ was/were + V.ing', 'While + was/were + V.ing', '["Past Continuous & Past Simple","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_094', 'english', 'ภาษาอังกฤษ', 'Regular', 1, 'Question Tags', 'She has never been to London before, ______? (Item 94)', '["has she","hasn''t she","is she","does she"]', 0, 'คำว่า ''never'' มีความหมายปฏิเสธ Question Tag จึงต้องเป็นบอกเล่า (has she)', 'never, rarely, seldom ถือเป็นปฏิเสธ', 'ประโยคปฏิเสธ -> Tag เป็นบอกเล่า', '["Question Tags","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_095', 'english', 'ภาษาอังกฤษ', 'Gifted', 2, 'Passive Voice', 'This famous bridge ______ over 100 years ago. (Item 95)', '["was built","built","has built","is building"]', 0, 'สะพานถูกสร้างในอดีต (Passive Voice): was/were + V3 -> was built', 'สะพานสร้างตัวเองไม่ได้ ต้องใช้รูปถูกกระทำ', 'สิ่งของ + ถูกกระทำ = was/were + V.3', '["Passive Voice","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_096', 'english', 'ภาษาอังกฤษ', 'Regular', 3, 'Relative Pronouns', 'The doctor ______ helped the injured child received an award. (Item 96)', '["who","which","whom","whose"]', 0, 'ใช้ ''who'' ขยายคำนามคน (The doctor) ที่ทำหน้าที่เป็นประธาน', 'which ใช้กับสัตว์/สิ่งของ', 'คนเป็นประธาน = who', '["Relative Pronouns","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_097', 'english', 'ภาษาอังกฤษ', 'Gifted', 1, 'Prepositions of Place & Time', 'The final exam will start ______ 8:30 AM on Monday morning. (Item 97)', '["at","in","on","by"]', 0, 'บอกเวลาเฉพาะเจาะจงของนาฬิกา ใช้บุพบท ''at'' (at 8:30 AM)', 'in ใช้กับเดือน/ปี, on ใช้กับวัน/วันที่, at ใช้กับเวลา', 'เวลาเจาะจง = at เสมอ', '["Prepositions of Place & Time","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_098', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Causative Verbs', 'The strict teacher let us ______ our dictionaries during the vocabulary test. (Item 98)', '["use","to use","using","used"]', 0, 'let + someone + V.inf (กริยาไม่ผัน ไม่มี to)', 'ห้ามใส่ to หลัง let/make', 'let / make + คน + V.inf (ห้ามมี to)', '["Causative Verbs","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_099', 'english', 'ภาษาอังกฤษ', 'Gifted', 3, 'Comparatives & Superlatives', 'Jupiter is ______ planet in our solar system. (Item 99)', '["the largest","larger","largest","the most large"]', 0, 'ขั้นสุดของคำพยางค์เดียวคือ the + adj-est -> the largest', 'ขั้นสุดต้องมี the เสมอ', 'ขั้นสุด = the + est', '["Comparatives & Superlatives","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('e_100', 'english', 'ภาษาอังกฤษ', 'Regular', 1, 'Present Perfect Tense', 'I have known my best friend ______ five years. (Item 100)', '["for","since","during","at"]', 0, 'ใช้ ''for'' นำหน้าจำนวนช่วงเวลา (for five years)', 'since ใช้กับจุดเริ่มต้นของเวลา เช่น since 2020', 'for + จำนวนเวลา / since + จุดเริ่มต้น', '["Present Perfect Tense","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_001', 'thai', 'ภาษาไทย', 'Gifted', 1, 'คำยืมภาษาต่างประเทศ (เขมร บาลี สันสกฤต)', 'ข้อใดเป็นคำยืมที่มาจากภาษาเขมรทุกคำ (ข้อที่ 1)', '["เสด็จ, บังคม, ถนน, เพ็ญ","ปัญญา, มัจฉา, บัลลังก์","ครุฑ, แพทย์, ปรัชญา","บะหมี่, เกี๊ยว, โต๊ะ"]', 0, 'เสด็จ, บังคม, ถนน, เพ็ญ แผลงมาจากภาษาเขมร', 'ถนน เพ็ญ ไม่ใช่คำไทยแท้', 'เขมรมักขึ้นต้น บัง-บัน-บำ, สระอำ, อักษรนำ', '["คำยืมภาษาต่างประเทศ (เขมร บาลี สันสกฤต)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_002', 'thai', 'ภาษาไทย', 'Regular', 2, 'คำสมาสและคำสนธิ', 'ข้อใดเป็นคำสมาสแบบมีสนธิ (เชื่อมกลืนเสียงสระ) ทุกคำ (ข้อที่ 2)', '["มโหฬาร, ราชูปโภค, วิทยาลัย","ราชการ, ผลไม้, รถไฟ","ประวัติศาสตร์, ภูมิศาสตร์","พลศึกษา, ทรัพยากร"]', 0, 'มหา+โอฬาร=มโหฬาร, ราช+อุปโภค=ราชูปโภค, วิทย+อาลัย=วิทยาลัย มีการเชื่อมกลืนเสียงสระ', 'ผลไม้ รถไฟ มีคำไทยปน ไม่ใช่สมาส', 'สนธิ = มีการกลืนเสียงสระเชื่อมคำ', '["คำสมาสและคำสนธิ","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_003', 'thai', 'ภาษาไทย', 'Gifted', 3, 'ชนิดของประโยค (ความเดียว ความรวม ความซ้อน)', 'ข้อใดจัดเป็นประโยคความซ้อน (สังกรประโยค) (ข้อที่ 3)', '["คุณครูชมเชยนักเรียนที่ตั้งใจทำข้อสอบอย่างสม่ำเสมอ","คุณพ่อและคุณแม่ไปออกกำลังกาย","น้องทำการบ้านแต่วินเล่นเกม","นกพิราบบินเกาะบนกิ่งไม้ใหญ่"]', 0, 'มีประโยคหลักและประโยคย่อยขยายนาม เชื่อมด้วยคำว่า ''ที่''', 'ประโยคเชื่อมด้วย ''แต่'' เป็นความรวม', 'ประโยคความซ้อนมักมีคำเชื่อม ที่, ซึ่ง, อัน, ผู้', '["ชนิดของประโยค (ความเดียว ความรวม ความซ้อน)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_004', 'thai', 'ภาษาไทย', 'Regular', 1, 'คำราชาศัพท์', 'คำราชาศัพท์ของ ''แว่นตา'' และ ''แหวน'' คือข้อใดตามลำดับ (ข้อที่ 4)', '["ฉลองพระเนตร, ธำมรงค์","พระเนตร, พระธำมรงค์","ฉลองพระบาท, พระกุณฑล","พระสนับเพลา, พระกรรเจียก"]', 0, 'ฉลองพระเนตร = แว่นตา, ธำมรงค์ = แหวน', 'พระเนตร คือ ดวงตา', 'ฉลองพระเนตร = แว่นตา / ธำมรงค์ = แหวน', '["คำราชาศัพท์","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_005', 'thai', 'ภาษาไทย', 'Gifted', 2, 'สำนวน สุภาษิต คำพังเพย', 'สำนวนใดหมายถึง ''การทำความดีโดยไม่หวังผลตอบแทนและไม่โอ้อวด'' (ข้อที่ 5)', '["ปิดทองหลังพระ","ชุบมือเปิบ","ขี่ช้างจับตั๊กแตน","ไก่เห็นตีนงู งูเห็นนมไก่"]', 0, 'ปิดทองหลังพระ คือ ทำความดีอย่างเงียบๆ', 'ชุบมือเปิบ = ฉวยประโยชน์', 'ทำดีไม่โอ้อวด = ปิดทองหลังพระ', '["สำนวน สุภาษิต คำพังเพย","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_006', 'thai', 'ภาษาไทย', 'Regular', 3, 'คำเป็น-คำตาย', 'ข้อใดประกอบด้วยคำตายทุกคำ (ข้อที่ 6)', '["มัก, ดุ, กะ, บท","กาล, นาน, มา, แล้ว","เรือ, ใบ, ใน, คลอง","เด็ก, ดี, มี, วินัย"]', 0, 'คำตายคือ ประสมสระสั้นไม่มีตัวสะกด หรือสะกดในแม่ กบด (กก, กบ, กด)', 'แม่กน กง กม เกย เกอว เป็นคำเป็น', 'คำตาย = กบด + สระสั้นไม่มีตัวสะกด', '["คำเป็น-คำตาย","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_007', 'thai', 'ภาษาไทย', 'Gifted', 1, 'อักษรควบแท้และควบไม่แท้', 'ข้อใดมีคำควบไม่แท้ปรากฏอยู่มากที่สุด (ข้อที่ 7)', '["ทรงสร้างสระน้ำเสริมทรัพย์สิน","กริชกรีดกรายกล้วยใกล้คลองกว้าง","ครูกล่าวตักเตือนคนเกียจคร้าน","พลอยเพลิดเพลินปลูกต้นพลับพลึง"]', 0, 'ทรง (ซ), สร้าง (ส), สระ (ส), เสริม (ส), ทรัพย์ (ซ) เป็นควบไม่แท้', 'กริช, กล้วย, ครู เป็นควบแท้', 'ทร ออกเสียง ซ = ควบไม่แท้', '["อักษรควบแท้และควบไม่แท้","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_008', 'thai', 'ภาษาไทย', 'Regular', 2, 'การสร้างคำ (คำประสม คำซ้อน คำซ้ำ)', 'ข้อใดจัดเป็นคำประสมทุกคำ (ข้อที่ 8)', '["แม่น้ำ, พ่อตา, รถไฟ, น้ำปลา","บ้านเรือน, เสื้อผ้า, หน้าตา","คนๆ, เร็วๆ, บ่อยๆ","กรรไกร, มะละกอ, นาฬิกา"]', 0, 'คำประสมเกิดจากคำมูลรวมกันเกิดความหมายใหม่', 'บ้านเรือน เสื้อผ้า เป็นคำซ้อน', 'คำมูล + คำมูล = เกิดความหมายใหม่', '["การสร้างคำ (คำประสม คำซ้อน คำซ้ำ)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_009', 'thai', 'ภาษาไทย', 'Gifted', 3, 'อักษรสามหมู่ (ไตรยางศ์)', 'พยัญชนะในข้อใดจัดอยู่ในกลุ่ม ''อักษรสูง'' ทั้งหมด (ข้อที่ 9)', '["ข, ฉ, ถ, ผ, ฝ, ส, ห","ก, จ, ด, ต, บ, ป, อ","ค, ช, ซ, ท, พ, ฟ, ฮ","ง, น, ม, ย, ร, ล, ว"]', 0, 'อักษรสูงมี 11 ตัว ท่องว่า ''ผีฝากถุงข้าวสารให้ฉัน''', 'ก จ ด ต บ ป อ คือ อักษรกลาง', 'อักษรสูง = ผี-ฝาก-ถุง-ข้าว-สาร-ให้-ฉัน', '["อักษรสามหมู่ (ไตรยางศ์)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_010', 'thai', 'ภาษาไทย', 'Regular', 1, 'คำไวพจน์ (คำพ้องความหมาย)', 'ข้อใดเป็นคำไวพจน์ที่มีความหมายตรงกับคำว่า ''ดอกไม้'' ทุกคำ (ข้อที่ 10)', '["บุปผา, ผกา, มาลี, สุมาลี","นภา, อัมพร, เวหา, ทิฆัมพร","สุริยา, ภาณุ, ตะวัน, ไถง","ชลธี, สาคร, วารี, อุทก"]', 0, 'บุปผา ผกา มาลี สุมาลี แปลว่า ดอกไม้', 'อัมพร แปลว่า ท้องฟ้า', 'บุปผา ผกา มาลี สุมาลี = ดอกไม้', '["คำไวพจน์ (คำพ้องความหมาย)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_011', 'thai', 'ภาษาไทย', 'Gifted', 2, 'คำยืมภาษาต่างประเทศ (เขมร บาลี สันสกฤต)', 'ข้อใดเป็นคำยืมที่มาจากภาษาเขมรทุกคำ (ข้อที่ 11)', '["เสด็จ, บังคม, ถนน, เพ็ญ","ปัญญา, มัจฉา, บัลลังก์","ครุฑ, แพทย์, ปรัชญา","บะหมี่, เกี๊ยว, โต๊ะ"]', 0, 'เสด็จ, บังคม, ถนน, เพ็ญ แผลงมาจากภาษาเขมร', 'ถนน เพ็ญ ไม่ใช่คำไทยแท้', 'เขมรมักขึ้นต้น บัง-บัน-บำ, สระอำ, อักษรนำ', '["คำยืมภาษาต่างประเทศ (เขมร บาลี สันสกฤต)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_012', 'thai', 'ภาษาไทย', 'Regular', 3, 'คำสมาสและคำสนธิ', 'ข้อใดเป็นคำสมาสแบบมีสนธิ (เชื่อมกลืนเสียงสระ) ทุกคำ (ข้อที่ 12)', '["มโหฬาร, ราชูปโภค, วิทยาลัย","ราชการ, ผลไม้, รถไฟ","ประวัติศาสตร์, ภูมิศาสตร์","พลศึกษา, ทรัพยากร"]', 0, 'มหา+โอฬาร=มโหฬาร, ราช+อุปโภค=ราชูปโภค, วิทย+อาลัย=วิทยาลัย มีการเชื่อมกลืนเสียงสระ', 'ผลไม้ รถไฟ มีคำไทยปน ไม่ใช่สมาส', 'สนธิ = มีการกลืนเสียงสระเชื่อมคำ', '["คำสมาสและคำสนธิ","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_013', 'thai', 'ภาษาไทย', 'Gifted', 1, 'ชนิดของประโยค (ความเดียว ความรวม ความซ้อน)', 'ข้อใดจัดเป็นประโยคความซ้อน (สังกรประโยค) (ข้อที่ 13)', '["คุณครูชมเชยนักเรียนที่ตั้งใจทำข้อสอบอย่างสม่ำเสมอ","คุณพ่อและคุณแม่ไปออกกำลังกาย","น้องทำการบ้านแต่วินเล่นเกม","นกพิราบบินเกาะบนกิ่งไม้ใหญ่"]', 0, 'มีประโยคหลักและประโยคย่อยขยายนาม เชื่อมด้วยคำว่า ''ที่''', 'ประโยคเชื่อมด้วย ''แต่'' เป็นความรวม', 'ประโยคความซ้อนมักมีคำเชื่อม ที่, ซึ่ง, อัน, ผู้', '["ชนิดของประโยค (ความเดียว ความรวม ความซ้อน)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_014', 'thai', 'ภาษาไทย', 'Regular', 2, 'คำราชาศัพท์', 'คำราชาศัพท์ของ ''แว่นตา'' และ ''แหวน'' คือข้อใดตามลำดับ (ข้อที่ 14)', '["ฉลองพระเนตร, ธำมรงค์","พระเนตร, พระธำมรงค์","ฉลองพระบาท, พระกุณฑล","พระสนับเพลา, พระกรรเจียก"]', 0, 'ฉลองพระเนตร = แว่นตา, ธำมรงค์ = แหวน', 'พระเนตร คือ ดวงตา', 'ฉลองพระเนตร = แว่นตา / ธำมรงค์ = แหวน', '["คำราชาศัพท์","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_015', 'thai', 'ภาษาไทย', 'Gifted', 3, 'สำนวน สุภาษิต คำพังเพย', 'สำนวนใดหมายถึง ''การทำความดีโดยไม่หวังผลตอบแทนและไม่โอ้อวด'' (ข้อที่ 15)', '["ปิดทองหลังพระ","ชุบมือเปิบ","ขี่ช้างจับตั๊กแตน","ไก่เห็นตีนงู งูเห็นนมไก่"]', 0, 'ปิดทองหลังพระ คือ ทำความดีอย่างเงียบๆ', 'ชุบมือเปิบ = ฉวยประโยชน์', 'ทำดีไม่โอ้อวด = ปิดทองหลังพระ', '["สำนวน สุภาษิต คำพังเพย","Gifted"]');
