INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_030', 'thai', 'ภาษาไทย', 'Regular', 3, 'คำไวพจน์ (คำพ้องความหมาย)', 'ข้อใดเป็นคำไวพจน์ที่มีความหมายตรงกับคำว่า ''ดอกไม้'' ทุกคำ (ข้อที่ 30)', '["บุปผา, ผกา, มาลี, สุมาลี","นภา, อัมพร, เวหา, ทิฆัมพร","สุริยา, ภาณุ, ตะวัน, ไถง","ชลธี, สาคร, วารี, อุทก"]', 0, 'บุปผา ผกา มาลี สุมาลี แปลว่า ดอกไม้', 'อัมพร แปลว่า ท้องฟ้า', 'บุปผา ผกา มาลี สุมาลี = ดอกไม้', '["คำไวพจน์ (คำพ้องความหมาย)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_031', 'thai', 'ภาษาไทย', 'Gifted', 1, 'คำยืมภาษาต่างประเทศ (เขมร บาลี สันสกฤต)', 'ข้อใดเป็นคำยืมที่มาจากภาษาเขมรทุกคำ (ข้อที่ 31)', '["เสด็จ, บังคม, ถนน, เพ็ญ","ปัญญา, มัจฉา, บัลลังก์","ครุฑ, แพทย์, ปรัชญา","บะหมี่, เกี๊ยว, โต๊ะ"]', 0, 'เสด็จ, บังคม, ถนน, เพ็ญ แผลงมาจากภาษาเขมร', 'ถนน เพ็ญ ไม่ใช่คำไทยแท้', 'เขมรมักขึ้นต้น บัง-บัน-บำ, สระอำ, อักษรนำ', '["คำยืมภาษาต่างประเทศ (เขมร บาลี สันสกฤต)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_032', 'thai', 'ภาษาไทย', 'Regular', 2, 'คำสมาสและคำสนธิ', 'ข้อใดเป็นคำสมาสแบบมีสนธิ (เชื่อมกลืนเสียงสระ) ทุกคำ (ข้อที่ 32)', '["มโหฬาร, ราชูปโภค, วิทยาลัย","ราชการ, ผลไม้, รถไฟ","ประวัติศาสตร์, ภูมิศาสตร์","พลศึกษา, ทรัพยากร"]', 0, 'มหา+โอฬาร=มโหฬาร, ราช+อุปโภค=ราชูปโภค, วิทย+อาลัย=วิทยาลัย มีการเชื่อมกลืนเสียงสระ', 'ผลไม้ รถไฟ มีคำไทยปน ไม่ใช่สมาส', 'สนธิ = มีการกลืนเสียงสระเชื่อมคำ', '["คำสมาสและคำสนธิ","Regular"]');
