INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_034', 'thai', 'ภาษาไทย', 'Regular', 1, 'คำราชาศัพท์', 'คำราชาศัพท์ของ ''แว่นตา'' และ ''แหวน'' คือข้อใดตามลำดับ (ข้อที่ 34)', '["ฉลองพระเนตร, ธำมรงค์","พระเนตร, พระธำมรงค์","ฉลองพระบาท, พระกุณฑล","พระสนับเพลา, พระกรรเจียก"]', 0, 'ฉลองพระเนตร = แว่นตา, ธำมรงค์ = แหวน', 'พระเนตร คือ ดวงตา', 'ฉลองพระเนตร = แว่นตา / ธำมรงค์ = แหวน', '["คำราชาศัพท์","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_035', 'thai', 'ภาษาไทย', 'Gifted', 2, 'สำนวน สุภาษิต คำพังเพย', 'สำนวนใดหมายถึง ''การทำความดีโดยไม่หวังผลตอบแทนและไม่โอ้อวด'' (ข้อที่ 35)', '["ปิดทองหลังพระ","ชุบมือเปิบ","ขี่ช้างจับตั๊กแตน","ไก่เห็นตีนงู งูเห็นนมไก่"]', 0, 'ปิดทองหลังพระ คือ ทำความดีอย่างเงียบๆ', 'ชุบมือเปิบ = ฉวยประโยชน์', 'ทำดีไม่โอ้อวด = ปิดทองหลังพระ', '["สำนวน สุภาษิต คำพังเพย","Gifted"]');
