INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_047', 'thai', 'ภาษาไทย', 'Gifted', 2, 'อักษรควบแท้และควบไม่แท้', 'ข้อใดมีคำควบไม่แท้ปรากฏอยู่มากที่สุด (ข้อที่ 47)', '["ทรงสร้างสระน้ำเสริมทรัพย์สิน","กริชกรีดกรายกล้วยใกล้คลองกว้าง","ครูกล่าวตักเตือนคนเกียจคร้าน","พลอยเพลิดเพลินปลูกต้นพลับพลึง"]', 0, 'ทรง (ซ), สร้าง (ส), สระ (ส), เสริม (ส), ทรัพย์ (ซ) เป็นควบไม่แท้', 'กริช, กล้วย, ครู เป็นควบแท้', 'ทร ออกเสียง ซ = ควบไม่แท้', '["อักษรควบแท้และควบไม่แท้","Gifted"]');
