INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_063', 'thai', 'ภาษาไทย', 'Gifted', 3, 'ชนิดของประโยค (ความเดียว ความรวม ความซ้อน)', 'ข้อใดจัดเป็นประโยคความซ้อน (สังกรประโยค) (ข้อที่ 63)', '["คุณครูชมเชยนักเรียนที่ตั้งใจทำข้อสอบอย่างสม่ำเสมอ","คุณพ่อและคุณแม่ไปออกกำลังกาย","น้องทำการบ้านแต่วินเล่นเกม","นกพิราบบินเกาะบนกิ่งไม้ใหญ่"]', 0, 'มีประโยคหลักและประโยคย่อยขยายนาม เชื่อมด้วยคำว่า ''ที่''', 'ประโยคเชื่อมด้วย ''แต่'' เป็นความรวม', 'ประโยคความซ้อนมักมีคำเชื่อม ที่, ซึ่ง, อัน, ผู้', '["ชนิดของประโยค (ความเดียว ความรวม ความซ้อน)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_064', 'thai', 'ภาษาไทย', 'Regular', 1, 'คำราชาศัพท์', 'คำราชาศัพท์ของ ''แว่นตา'' และ ''แหวน'' คือข้อใดตามลำดับ (ข้อที่ 64)', '["ฉลองพระเนตร, ธำมรงค์","พระเนตร, พระธำมรงค์","ฉลองพระบาท, พระกุณฑล","พระสนับเพลา, พระกรรเจียก"]', 0, 'ฉลองพระเนตร = แว่นตา, ธำมรงค์ = แหวน', 'พระเนตร คือ ดวงตา', 'ฉลองพระเนตร = แว่นตา / ธำมรงค์ = แหวน', '["คำราชาศัพท์","Regular"]');
