INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_095', 'thai', 'ภาษาไทย', 'Gifted', 2, 'สำนวน สุภาษิต คำพังเพย', 'สำนวนใดหมายถึง ''การทำความดีโดยไม่หวังผลตอบแทนและไม่โอ้อวด'' (ข้อที่ 95)', '["ปิดทองหลังพระ","ชุบมือเปิบ","ขี่ช้างจับตั๊กแตน","ไก่เห็นตีนงู งูเห็นนมไก่"]', 0, 'ปิดทองหลังพระ คือ ทำความดีอย่างเงียบๆ', 'ชุบมือเปิบ = ฉวยประโยชน์', 'ทำดีไม่โอ้อวด = ปิดทองหลังพระ', '["สำนวน สุภาษิต คำพังเพย","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_096', 'thai', 'ภาษาไทย', 'Regular', 3, 'คำเป็น-คำตาย', 'ข้อใดประกอบด้วยคำตายทุกคำ (ข้อที่ 96)', '["มัก, ดุ, กะ, บท","กาล, นาน, มา, แล้ว","เรือ, ใบ, ใน, คลอง","เด็ก, ดี, มี, วินัย"]', 0, 'คำตายคือ ประสมสระสั้นไม่มีตัวสะกด หรือสะกดในแม่ กบด (กก, กบ, กด)', 'แม่กน กง กม เกย เกอว เป็นคำเป็น', 'คำตาย = กบด + สระสั้นไม่มีตัวสะกด', '["คำเป็น-คำตาย","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_097', 'thai', 'ภาษาไทย', 'Gifted', 1, 'อักษรควบแท้และควบไม่แท้', 'ข้อใดมีคำควบไม่แท้ปรากฏอยู่มากที่สุด (ข้อที่ 97)', '["ทรงสร้างสระน้ำเสริมทรัพย์สิน","กริชกรีดกรายกล้วยใกล้คลองกว้าง","ครูกล่าวตักเตือนคนเกียจคร้าน","พลอยเพลิดเพลินปลูกต้นพลับพลึง"]', 0, 'ทรง (ซ), สร้าง (ส), สระ (ส), เสริม (ส), ทรัพย์ (ซ) เป็นควบไม่แท้', 'กริช, กล้วย, ครู เป็นควบแท้', 'ทร ออกเสียง ซ = ควบไม่แท้', '["อักษรควบแท้และควบไม่แท้","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_098', 'thai', 'ภาษาไทย', 'Regular', 2, 'การสร้างคำ (คำประสม คำซ้อน คำซ้ำ)', 'ข้อใดจัดเป็นคำประสมทุกคำ (ข้อที่ 98)', '["แม่น้ำ, พ่อตา, รถไฟ, น้ำปลา","บ้านเรือน, เสื้อผ้า, หน้าตา","คนๆ, เร็วๆ, บ่อยๆ","กรรไกร, มะละกอ, นาฬิกา"]', 0, 'คำประสมเกิดจากคำมูลรวมกันเกิดความหมายใหม่', 'บ้านเรือน เสื้อผ้า เป็นคำซ้อน', 'คำมูล + คำมูล = เกิดความหมายใหม่', '["การสร้างคำ (คำประสม คำซ้อน คำซ้ำ)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_099', 'thai', 'ภาษาไทย', 'Gifted', 3, 'อักษรสามหมู่ (ไตรยางศ์)', 'พยัญชนะในข้อใดจัดอยู่ในกลุ่ม ''อักษรสูง'' ทั้งหมด (ข้อที่ 99)', '["ข, ฉ, ถ, ผ, ฝ, ส, ห","ก, จ, ด, ต, บ, ป, อ","ค, ช, ซ, ท, พ, ฟ, ฮ","ง, น, ม, ย, ร, ล, ว"]', 0, 'อักษรสูงมี 11 ตัว ท่องว่า ''ผีฝากถุงข้าวสารให้ฉัน''', 'ก จ ด ต บ ป อ คือ อักษรกลาง', 'อักษรสูง = ผี-ฝาก-ถุง-ข้าว-สาร-ให้-ฉัน', '["อักษรสามหมู่ (ไตรยางศ์)","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('t_100', 'thai', 'ภาษาไทย', 'Regular', 1, 'คำไวพจน์ (คำพ้องความหมาย)', 'ข้อใดเป็นคำไวพจน์ที่มีความหมายตรงกับคำว่า ''ดอกไม้'' ทุกคำ (ข้อที่ 100)', '["บุปผา, ผกา, มาลี, สุมาลี","นภา, อัมพร, เวหา, ทิฆัมพร","สุริยา, ภาณุ, ตะวัน, ไถง","ชลธี, สาคร, วารี, อุทก"]', 0, 'บุปผา ผกา มาลี สุมาลี แปลว่า ดอกไม้', 'อัมพร แปลว่า ท้องฟ้า', 'บุปผา ผกา มาลี สุมาลี = ดอกไม้', '["คำไวพจน์ (คำพ้องความหมาย)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_001', 'social', 'สังคมศึกษา', 'Gifted', 1, 'ประวัติศาสตร์ไทย: การปฏิรูป ร.5', 'รัชกาลที่ 5 ทรงปฏิรูปการปกครองส่วนกลางโดยยกเลิกจตุสดมภ์และตั้งหน่วยงานใดแทน (ข้อที่ 1)', '["การจัดตั้ง 12 กระทรวง มีเสนาบดีเป็นหัวหน้า","การจัดตั้งมณฑลเทศาภิบาล","การจัดตั้งสภาผู้แทนราษฎร","การจัดตั้งระบบสมุหนายก"]', 0, 'พ.ศ. 2435 ร.5 ทรงตั้ง 12 กระทรวงบริหารส่วนกลาง', 'มณฑลเทศาภิบาลเป็นการปฏิรูปส่วนภูมิภาค', 'ส่วนกลาง ร.5 = ตั้ง 12 กระทรวง', '["ประวัติศาสตร์ไทย: การปฏิรูป ร.5","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_002', 'social', 'สังคมศึกษา', 'Regular', 2, 'ภูมิศาสตร์ไทย: ลมมรสุม', 'ลมมรสุมตะวันออกเฉียงเหนือพัดผ่านไทยช่วงเดือนใดและส่งผลอย่างไร (ข้อที่ 2)', '["พ.ย. - ก.พ. ทำให้ภาคเหนือหนาวเย็น แต่ภาคใต้ฝั่งอ่าวไทยฝนตกชุก","พ.ค. - ต.ค. ฝนตกชุกทั่วประเทศ","มี.ค. - พ.ค. ร้อนจัดทั่วประเทศ","พ.ย. - ก.พ. อันดามันคลื่นลมแรงสุด"]', 0, 'พัดความหนาวจากจีนเข้าไทย พ.ย.-ก.พ. และพาฝนตกหนักอ่าวไทย', 'ภาคใต้ฝั่งอ่าวไทยจะมีฝนชุกในฤดูหนาว', 'มรสุม ตอ.เฉียงเหนือ = เหนือหนาว อ่าวไทยฝนตก', '["ภูมิศาสตร์ไทย: ลมมรสุม","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_003', 'social', 'สังคมศึกษา', 'Gifted', 3, 'เศรษฐศาสตร์: กลไกราคาและอุปสงค์-อุปทาน', 'ตามกฎของอุปสงค์ (Law of Demand) เมื่อราคาสินค้าปรับตัวสูงขึ้น ปริมาณซื้อจะเป็นอย่างไร (ข้อที่ 3)', '["ลดลง เพราะผู้บริโภครู้สึกว่าแพงขึ้นและหันไปหาสินค้าทดแทน","เพิ่มขึ้น เพราะคุณภาพดีขึ้น","คงที่เสมอ","เพิ่มขึ้นเป็นสองเท่า"]', 0, 'กฎอุปสงค์: ราคาและปริมาณซื้อแปรผกผันกัน (แพงขึ้น -> ซื้อน้อยลง)', 'อย่าสับสนกับอุปทานของผู้ขาย', 'อุปสงค์ = ของแพง ซื้อลดลง', '["เศรษฐศาสตร์: กลไกราคาและอุปสงค์-อุปทาน","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_004', 'social', 'สังคมศึกษา', 'Regular', 1, 'ศาสนาและจริยธรรม: อิทธิบาท 4', 'หลักธรรมอิทธิบาท 4 ข้อใดที่หมายถึง ''ความขยันหมั่นเพียร ไม่ย่อท้อ'' (ข้อที่ 4)', '["วิริยะ","ฉันทะ","จิตตะ","วิมังสา"]', 0, 'ฉันทะ (รักงาน), วิริยะ (พากเพียร), จิตตะ (จดจ่อ), วิมังสา (ทบทวน)', 'ฉันทะ คือความรักความพอใจ', 'ฉัน-วิ-จิต-วิม = รัก-เพียร-จดจ่อ-ไตร่ตรอง', '["ศาสนาและจริยธรรม: อิทธิบาท 4","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_005', 'social', 'สังคมศึกษา', 'Gifted', 2, 'หน้าที่พลเมืองและรัฐธรรมนูญ', 'อำนาจอธิปไตยของปวงชนชาวไทยตามรัฐธรรมนูญ แบ่งออกเป็น 3 อำนาจ ได้แก่อำนาจใด (ข้อที่ 5)', '["นิติบัญญัติ, บริหาร, ตุลาการ","ประธานาธิบดี, รัฐสภา, ศาล","เทศบาล, อบจ., อบต.","ข้าราชการ, ทหาร, ตำรวจ"]', 0, 'อำนาจอธิปไตยแบ่งเป็น: นิติบัญญัติ (รัฐสภา), บริหาร (ครม.), ตุลาการ (ศาล)', 'อย่าสับสนกับการปกครองท้องถิ่น', 'อำนาจอธิปไตย = นิติบัญญัติ + บริหาร + ตุลาการ', '["หน้าที่พลเมืองและรัฐธรรมนูญ","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_006', 'social', 'สังคมศึกษา', 'Regular', 3, 'ประวัติศาสตร์สมัยสุโขทัย', 'การปกครองสมัยสุโขทัยตอนต้นมีลักษณะเด่นตรงกับข้อใด (ข้อที่ 6)', '["การปกครองแบบปิตุราชา (พ่อปกครองลูก)","การปกครองแบบเทวราชา (สมมติเทพ)","การปกครองแบบธรรมราชา","การปกครองระบอบเทศาภิบาล"]', 0, 'สุโขทัยตอนต้นกษัตริย์ใกล้ชิดราษฎร มีการแขวนกระดิ่งร้องทุกข์', 'เทวราชาเริ่มรับอิทธิพลขอมในสมัยอยุธยา', 'สุโขทัยตอนต้น = แขวนกระดิ่ง = พ่อปกครองลูก', '["ประวัติศาสตร์สมัยสุโขทัย","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_007', 'social', 'สังคมศึกษา', 'Gifted', 1, 'เศรษฐศาสตร์: ระบบสหกรณ์', 'หลักการสำคัญที่สุดของระบบสหกรณ์ที่ต่างจากบริษัทเอกชนคือข้อใด (ข้อที่ 7)', '["สมาชิกทุกคนมีสิทธิออกเสียงคนละ 1 เสียงเท่ากัน ไม่ขึ้นกับจำนวนหุ้น","ผู้ถือหุ้นมากสุดมีสิทธิตัดสินใจ","รัฐบาลเป็นเจ้าของทั้งหมด","ห้ามจ่ายเงินปันผล"]', 0, 'สหกรณ์ยึดหลักประชาธิปไตย 1 คน 1 เสียง เท่าเทียมกัน', 'บริษัทจำกัดออกเสียงตามจำนวนหุ้น แต่สหกรณ์ 1 คน = 1 เสียง', 'สหกรณ์ = 1 คน 1 เสียง เท่าเทียมกัน', '["เศรษฐศาสตร์: ระบบสหกรณ์","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_008', 'social', 'สังคมศึกษา', 'Regular', 2, 'ภูมิศาสตร์: พิกัดแผนที่', 'เส้นสมมติแนวนอนที่ลากขนานกับเส้นศูนย์สูตรเพื่อบอกตำแหน่งเหนือ-ใต้ เรียกว่าอะไร (ข้อที่ 8)', '["เส้นละติจูด (Latitude / เส้นรุ้ง)","เส้นลองจิจูด (Longitude / เส้นแวง)","เส้นเมริเดียนแรก","เส้นเขตวันสากล"]', 0, 'เส้นละติจูด (รุ้งตะแคง) ลากแนวนอนบอกเหนือ-ใต้ ส่วนลองจิจูด (แวงตั้ง) บอกเวลา', 'จำสลับระหว่างรุ้งกับแวง', 'รุ้งตะแคง (ละติจูด) / แวงตั้ง (ลองจิจูด)', '["ภูมิศาสตร์: พิกัดแผนที่","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_009', 'social', 'สังคมศึกษา', 'Gifted', 3, 'กฎหมายเบื้องต้นและสิทธิเด็ก', 'สิทธิในการมีชีวิตรอด ได้รับการเลี้ยงดู และรักษาพยาบาล จัดอยู่ในสิทธิข้อใด (ข้อที่ 9)', '["สิทธิที่จะมีชีวิตรอด (Right to Survival)","สิทธิที่จะได้รับการพัฒนา","สิทธิในการมีส่วนร่วม","สิทธิที่จะได้รับการปกป้องคุ้มครอง"]', 0, 'สิทธิที่จะมีชีวิตรอดครอบคลุมการเกิด การรักษาพยาบาล อาหาร และที่อยู่อาศัย', 'สิทธิการศึกษาจัดอยู่ใน สิทธิที่จะได้รับการพัฒนา', 'อาหาร + พยาบาล = สิทธิที่จะมีชีวิตรอด', '["กฎหมายเบื้องต้นและสิทธิเด็ก","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_010', 'social', 'สังคมศึกษา', 'Regular', 1, 'ประชาคมอาเซียน (ASEAN)', 'สำนักงานเลขาธิการอาเซียน (ASEAN Secretariat) ตั้งอยู่ที่เมืองหลวงของประเทศใด (ข้อที่ 10)', '["กรุงจาการ์ตา ประเทศอินโดนีเซีย","กรุงเทพมหานคร ประเทศไทย","กรุงกัวลาลัมเปอร์ ประเทศมาเลเซีย","ประเทศสิงคโปร์"]', 0, 'สำนักงานใหญ่เลขาธิการอาเซียนตั้งอยู่ที่กรุงจาการ์ตา ประเทศอินโดนีเซีย', 'แม้ก่อตั้งที่กรุงเทพฯ แต่สำนักงานใหญ่อยู่ที่จาการ์ตา', 'สำนักงานใหญ่เลขาธิการอาเซียน = กรุงจาการ์ตา', '["ประชาคมอาเซียน (ASEAN)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_011', 'social', 'สังคมศึกษา', 'Gifted', 2, 'ประวัติศาสตร์ไทย: การปฏิรูป ร.5', 'รัชกาลที่ 5 ทรงปฏิรูปการปกครองส่วนกลางโดยยกเลิกจตุสดมภ์และตั้งหน่วยงานใดแทน (ข้อที่ 11)', '["การจัดตั้ง 12 กระทรวง มีเสนาบดีเป็นหัวหน้า","การจัดตั้งมณฑลเทศาภิบาล","การจัดตั้งสภาผู้แทนราษฎร","การจัดตั้งระบบสมุหนายก"]', 0, 'พ.ศ. 2435 ร.5 ทรงตั้ง 12 กระทรวงบริหารส่วนกลาง', 'มณฑลเทศาภิบาลเป็นการปฏิรูปส่วนภูมิภาค', 'ส่วนกลาง ร.5 = ตั้ง 12 กระทรวง', '["ประวัติศาสตร์ไทย: การปฏิรูป ร.5","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_012', 'social', 'สังคมศึกษา', 'Regular', 3, 'ภูมิศาสตร์ไทย: ลมมรสุม', 'ลมมรสุมตะวันออกเฉียงเหนือพัดผ่านไทยช่วงเดือนใดและส่งผลอย่างไร (ข้อที่ 12)', '["พ.ย. - ก.พ. ทำให้ภาคเหนือหนาวเย็น แต่ภาคใต้ฝั่งอ่าวไทยฝนตกชุก","พ.ค. - ต.ค. ฝนตกชุกทั่วประเทศ","มี.ค. - พ.ค. ร้อนจัดทั่วประเทศ","พ.ย. - ก.พ. อันดามันคลื่นลมแรงสุด"]', 0, 'พัดความหนาวจากจีนเข้าไทย พ.ย.-ก.พ. และพาฝนตกหนักอ่าวไทย', 'ภาคใต้ฝั่งอ่าวไทยจะมีฝนชุกในฤดูหนาว', 'มรสุม ตอ.เฉียงเหนือ = เหนือหนาว อ่าวไทยฝนตก', '["ภูมิศาสตร์ไทย: ลมมรสุม","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_013', 'social', 'สังคมศึกษา', 'Gifted', 1, 'เศรษฐศาสตร์: กลไกราคาและอุปสงค์-อุปทาน', 'ตามกฎของอุปสงค์ (Law of Demand) เมื่อราคาสินค้าปรับตัวสูงขึ้น ปริมาณซื้อจะเป็นอย่างไร (ข้อที่ 13)', '["ลดลง เพราะผู้บริโภครู้สึกว่าแพงขึ้นและหันไปหาสินค้าทดแทน","เพิ่มขึ้น เพราะคุณภาพดีขึ้น","คงที่เสมอ","เพิ่มขึ้นเป็นสองเท่า"]', 0, 'กฎอุปสงค์: ราคาและปริมาณซื้อแปรผกผันกัน (แพงขึ้น -> ซื้อน้อยลง)', 'อย่าสับสนกับอุปทานของผู้ขาย', 'อุปสงค์ = ของแพง ซื้อลดลง', '["เศรษฐศาสตร์: กลไกราคาและอุปสงค์-อุปทาน","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_014', 'social', 'สังคมศึกษา', 'Regular', 2, 'ศาสนาและจริยธรรม: อิทธิบาท 4', 'หลักธรรมอิทธิบาท 4 ข้อใดที่หมายถึง ''ความขยันหมั่นเพียร ไม่ย่อท้อ'' (ข้อที่ 14)', '["วิริยะ","ฉันทะ","จิตตะ","วิมังสา"]', 0, 'ฉันทะ (รักงาน), วิริยะ (พากเพียร), จิตตะ (จดจ่อ), วิมังสา (ทบทวน)', 'ฉันทะ คือความรักความพอใจ', 'ฉัน-วิ-จิต-วิม = รัก-เพียร-จดจ่อ-ไตร่ตรอง', '["ศาสนาและจริยธรรม: อิทธิบาท 4","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_015', 'social', 'สังคมศึกษา', 'Gifted', 3, 'หน้าที่พลเมืองและรัฐธรรมนูญ', 'อำนาจอธิปไตยของปวงชนชาวไทยตามรัฐธรรมนูญ แบ่งออกเป็น 3 อำนาจ ได้แก่อำนาจใด (ข้อที่ 15)', '["นิติบัญญัติ, บริหาร, ตุลาการ","ประธานาธิบดี, รัฐสภา, ศาล","เทศบาล, อบจ., อบต.","ข้าราชการ, ทหาร, ตำรวจ"]', 0, 'อำนาจอธิปไตยแบ่งเป็น: นิติบัญญัติ (รัฐสภา), บริหาร (ครม.), ตุลาการ (ศาล)', 'อย่าสับสนกับการปกครองท้องถิ่น', 'อำนาจอธิปไตย = นิติบัญญัติ + บริหาร + ตุลาการ', '["หน้าที่พลเมืองและรัฐธรรมนูญ","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_016', 'social', 'สังคมศึกษา', 'Regular', 1, 'ประวัติศาสตร์สมัยสุโขทัย', 'การปกครองสมัยสุโขทัยตอนต้นมีลักษณะเด่นตรงกับข้อใด (ข้อที่ 16)', '["การปกครองแบบปิตุราชา (พ่อปกครองลูก)","การปกครองแบบเทวราชา (สมมติเทพ)","การปกครองแบบธรรมราชา","การปกครองระบอบเทศาภิบาล"]', 0, 'สุโขทัยตอนต้นกษัตริย์ใกล้ชิดราษฎร มีการแขวนกระดิ่งร้องทุกข์', 'เทวราชาเริ่มรับอิทธิพลขอมในสมัยอยุธยา', 'สุโขทัยตอนต้น = แขวนกระดิ่ง = พ่อปกครองลูก', '["ประวัติศาสตร์สมัยสุโขทัย","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_017', 'social', 'สังคมศึกษา', 'Gifted', 2, 'เศรษฐศาสตร์: ระบบสหกรณ์', 'หลักการสำคัญที่สุดของระบบสหกรณ์ที่ต่างจากบริษัทเอกชนคือข้อใด (ข้อที่ 17)', '["สมาชิกทุกคนมีสิทธิออกเสียงคนละ 1 เสียงเท่ากัน ไม่ขึ้นกับจำนวนหุ้น","ผู้ถือหุ้นมากสุดมีสิทธิตัดสินใจ","รัฐบาลเป็นเจ้าของทั้งหมด","ห้ามจ่ายเงินปันผล"]', 0, 'สหกรณ์ยึดหลักประชาธิปไตย 1 คน 1 เสียง เท่าเทียมกัน', 'บริษัทจำกัดออกเสียงตามจำนวนหุ้น แต่สหกรณ์ 1 คน = 1 เสียง', 'สหกรณ์ = 1 คน 1 เสียง เท่าเทียมกัน', '["เศรษฐศาสตร์: ระบบสหกรณ์","Gifted"]');
