INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_037', 'social', 'สังคมศึกษา', 'Gifted', 1, 'เศรษฐศาสตร์: ระบบสหกรณ์', 'หลักการสำคัญที่สุดของระบบสหกรณ์ที่ต่างจากบริษัทเอกชนคือข้อใด (ข้อที่ 37)', '["สมาชิกทุกคนมีสิทธิออกเสียงคนละ 1 เสียงเท่ากัน ไม่ขึ้นกับจำนวนหุ้น","ผู้ถือหุ้นมากสุดมีสิทธิตัดสินใจ","รัฐบาลเป็นเจ้าของทั้งหมด","ห้ามจ่ายเงินปันผล"]', 0, 'สหกรณ์ยึดหลักประชาธิปไตย 1 คน 1 เสียง เท่าเทียมกัน', 'บริษัทจำกัดออกเสียงตามจำนวนหุ้น แต่สหกรณ์ 1 คน = 1 เสียง', 'สหกรณ์ = 1 คน 1 เสียง เท่าเทียมกัน', '["เศรษฐศาสตร์: ระบบสหกรณ์","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_038', 'social', 'สังคมศึกษา', 'Regular', 2, 'ภูมิศาสตร์: พิกัดแผนที่', 'เส้นสมมติแนวนอนที่ลากขนานกับเส้นศูนย์สูตรเพื่อบอกตำแหน่งเหนือ-ใต้ เรียกว่าอะไร (ข้อที่ 38)', '["เส้นละติจูด (Latitude / เส้นรุ้ง)","เส้นลองจิจูด (Longitude / เส้นแวง)","เส้นเมริเดียนแรก","เส้นเขตวันสากล"]', 0, 'เส้นละติจูด (รุ้งตะแคง) ลากแนวนอนบอกเหนือ-ใต้ ส่วนลองจิจูด (แวงตั้ง) บอกเวลา', 'จำสลับระหว่างรุ้งกับแวง', 'รุ้งตะแคง (ละติจูด) / แวงตั้ง (ลองจิจูด)', '["ภูมิศาสตร์: พิกัดแผนที่","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_039', 'social', 'สังคมศึกษา', 'Gifted', 3, 'กฎหมายเบื้องต้นและสิทธิเด็ก', 'สิทธิในการมีชีวิตรอด ได้รับการเลี้ยงดู และรักษาพยาบาล จัดอยู่ในสิทธิข้อใด (ข้อที่ 39)', '["สิทธิที่จะมีชีวิตรอด (Right to Survival)","สิทธิที่จะได้รับการพัฒนา","สิทธิในการมีส่วนร่วม","สิทธิที่จะได้รับการปกป้องคุ้มครอง"]', 0, 'สิทธิที่จะมีชีวิตรอดครอบคลุมการเกิด การรักษาพยาบาล อาหาร และที่อยู่อาศัย', 'สิทธิการศึกษาจัดอยู่ใน สิทธิที่จะได้รับการพัฒนา', 'อาหาร + พยาบาล = สิทธิที่จะมีชีวิตรอด', '["กฎหมายเบื้องต้นและสิทธิเด็ก","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_040', 'social', 'สังคมศึกษา', 'Regular', 1, 'ประชาคมอาเซียน (ASEAN)', 'สำนักงานเลขาธิการอาเซียน (ASEAN Secretariat) ตั้งอยู่ที่เมืองหลวงของประเทศใด (ข้อที่ 40)', '["กรุงจาการ์ตา ประเทศอินโดนีเซีย","กรุงเทพมหานคร ประเทศไทย","กรุงกัวลาลัมเปอร์ ประเทศมาเลเซีย","ประเทศสิงคโปร์"]', 0, 'สำนักงานใหญ่เลขาธิการอาเซียนตั้งอยู่ที่กรุงจาการ์ตา ประเทศอินโดนีเซีย', 'แม้ก่อตั้งที่กรุงเทพฯ แต่สำนักงานใหญ่อยู่ที่จาการ์ตา', 'สำนักงานใหญ่เลขาธิการอาเซียน = กรุงจาการ์ตา', '["ประชาคมอาเซียน (ASEAN)","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_041', 'social', 'สังคมศึกษา', 'Gifted', 2, 'ประวัติศาสตร์ไทย: การปฏิรูป ร.5', 'รัชกาลที่ 5 ทรงปฏิรูปการปกครองส่วนกลางโดยยกเลิกจตุสดมภ์และตั้งหน่วยงานใดแทน (ข้อที่ 41)', '["การจัดตั้ง 12 กระทรวง มีเสนาบดีเป็นหัวหน้า","การจัดตั้งมณฑลเทศาภิบาล","การจัดตั้งสภาผู้แทนราษฎร","การจัดตั้งระบบสมุหนายก"]', 0, 'พ.ศ. 2435 ร.5 ทรงตั้ง 12 กระทรวงบริหารส่วนกลาง', 'มณฑลเทศาภิบาลเป็นการปฏิรูปส่วนภูมิภาค', 'ส่วนกลาง ร.5 = ตั้ง 12 กระทรวง', '["ประวัติศาสตร์ไทย: การปฏิรูป ร.5","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_042', 'social', 'สังคมศึกษา', 'Regular', 3, 'ภูมิศาสตร์ไทย: ลมมรสุม', 'ลมมรสุมตะวันออกเฉียงเหนือพัดผ่านไทยช่วงเดือนใดและส่งผลอย่างไร (ข้อที่ 42)', '["พ.ย. - ก.พ. ทำให้ภาคเหนือหนาวเย็น แต่ภาคใต้ฝั่งอ่าวไทยฝนตกชุก","พ.ค. - ต.ค. ฝนตกชุกทั่วประเทศ","มี.ค. - พ.ค. ร้อนจัดทั่วประเทศ","พ.ย. - ก.พ. อันดามันคลื่นลมแรงสุด"]', 0, 'พัดความหนาวจากจีนเข้าไทย พ.ย.-ก.พ. และพาฝนตกหนักอ่าวไทย', 'ภาคใต้ฝั่งอ่าวไทยจะมีฝนชุกในฤดูหนาว', 'มรสุม ตอ.เฉียงเหนือ = เหนือหนาว อ่าวไทยฝนตก', '["ภูมิศาสตร์ไทย: ลมมรสุม","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_043', 'social', 'สังคมศึกษา', 'Gifted', 1, 'เศรษฐศาสตร์: กลไกราคาและอุปสงค์-อุปทาน', 'ตามกฎของอุปสงค์ (Law of Demand) เมื่อราคาสินค้าปรับตัวสูงขึ้น ปริมาณซื้อจะเป็นอย่างไร (ข้อที่ 43)', '["ลดลง เพราะผู้บริโภครู้สึกว่าแพงขึ้นและหันไปหาสินค้าทดแทน","เพิ่มขึ้น เพราะคุณภาพดีขึ้น","คงที่เสมอ","เพิ่มขึ้นเป็นสองเท่า"]', 0, 'กฎอุปสงค์: ราคาและปริมาณซื้อแปรผกผันกัน (แพงขึ้น -> ซื้อน้อยลง)', 'อย่าสับสนกับอุปทานของผู้ขาย', 'อุปสงค์ = ของแพง ซื้อลดลง', '["เศรษฐศาสตร์: กลไกราคาและอุปสงค์-อุปทาน","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_044', 'social', 'สังคมศึกษา', 'Regular', 2, 'ศาสนาและจริยธรรม: อิทธิบาท 4', 'หลักธรรมอิทธิบาท 4 ข้อใดที่หมายถึง ''ความขยันหมั่นเพียร ไม่ย่อท้อ'' (ข้อที่ 44)', '["วิริยะ","ฉันทะ","จิตตะ","วิมังสา"]', 0, 'ฉันทะ (รักงาน), วิริยะ (พากเพียร), จิตตะ (จดจ่อ), วิมังสา (ทบทวน)', 'ฉันทะ คือความรักความพอใจ', 'ฉัน-วิ-จิต-วิม = รัก-เพียร-จดจ่อ-ไตร่ตรอง', '["ศาสนาและจริยธรรม: อิทธิบาท 4","Regular"]');
