INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_051', 'social', 'สังคมศึกษา', 'Gifted', 3, 'ประวัติศาสตร์ไทย: การปฏิรูป ร.5', 'รัชกาลที่ 5 ทรงปฏิรูปการปกครองส่วนกลางโดยยกเลิกจตุสดมภ์และตั้งหน่วยงานใดแทน (ข้อที่ 51)', '["การจัดตั้ง 12 กระทรวง มีเสนาบดีเป็นหัวหน้า","การจัดตั้งมณฑลเทศาภิบาล","การจัดตั้งสภาผู้แทนราษฎร","การจัดตั้งระบบสมุหนายก"]', 0, 'พ.ศ. 2435 ร.5 ทรงตั้ง 12 กระทรวงบริหารส่วนกลาง', 'มณฑลเทศาภิบาลเป็นการปฏิรูปส่วนภูมิภาค', 'ส่วนกลาง ร.5 = ตั้ง 12 กระทรวง', '["ประวัติศาสตร์ไทย: การปฏิรูป ร.5","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_052', 'social', 'สังคมศึกษา', 'Regular', 1, 'ภูมิศาสตร์ไทย: ลมมรสุม', 'ลมมรสุมตะวันออกเฉียงเหนือพัดผ่านไทยช่วงเดือนใดและส่งผลอย่างไร (ข้อที่ 52)', '["พ.ย. - ก.พ. ทำให้ภาคเหนือหนาวเย็น แต่ภาคใต้ฝั่งอ่าวไทยฝนตกชุก","พ.ค. - ต.ค. ฝนตกชุกทั่วประเทศ","มี.ค. - พ.ค. ร้อนจัดทั่วประเทศ","พ.ย. - ก.พ. อันดามันคลื่นลมแรงสุด"]', 0, 'พัดความหนาวจากจีนเข้าไทย พ.ย.-ก.พ. และพาฝนตกหนักอ่าวไทย', 'ภาคใต้ฝั่งอ่าวไทยจะมีฝนชุกในฤดูหนาว', 'มรสุม ตอ.เฉียงเหนือ = เหนือหนาว อ่าวไทยฝนตก', '["ภูมิศาสตร์ไทย: ลมมรสุม","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_053', 'social', 'สังคมศึกษา', 'Gifted', 2, 'เศรษฐศาสตร์: กลไกราคาและอุปสงค์-อุปทาน', 'ตามกฎของอุปสงค์ (Law of Demand) เมื่อราคาสินค้าปรับตัวสูงขึ้น ปริมาณซื้อจะเป็นอย่างไร (ข้อที่ 53)', '["ลดลง เพราะผู้บริโภครู้สึกว่าแพงขึ้นและหันไปหาสินค้าทดแทน","เพิ่มขึ้น เพราะคุณภาพดีขึ้น","คงที่เสมอ","เพิ่มขึ้นเป็นสองเท่า"]', 0, 'กฎอุปสงค์: ราคาและปริมาณซื้อแปรผกผันกัน (แพงขึ้น -> ซื้อน้อยลง)', 'อย่าสับสนกับอุปทานของผู้ขาย', 'อุปสงค์ = ของแพง ซื้อลดลง', '["เศรษฐศาสตร์: กลไกราคาและอุปสงค์-อุปทาน","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_054', 'social', 'สังคมศึกษา', 'Regular', 3, 'ศาสนาและจริยธรรม: อิทธิบาท 4', 'หลักธรรมอิทธิบาท 4 ข้อใดที่หมายถึง ''ความขยันหมั่นเพียร ไม่ย่อท้อ'' (ข้อที่ 54)', '["วิริยะ","ฉันทะ","จิตตะ","วิมังสา"]', 0, 'ฉันทะ (รักงาน), วิริยะ (พากเพียร), จิตตะ (จดจ่อ), วิมังสา (ทบทวน)', 'ฉันทะ คือความรักความพอใจ', 'ฉัน-วิ-จิต-วิม = รัก-เพียร-จดจ่อ-ไตร่ตรอง', '["ศาสนาและจริยธรรม: อิทธิบาท 4","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_055', 'social', 'สังคมศึกษา', 'Gifted', 1, 'หน้าที่พลเมืองและรัฐธรรมนูญ', 'อำนาจอธิปไตยของปวงชนชาวไทยตามรัฐธรรมนูญ แบ่งออกเป็น 3 อำนาจ ได้แก่อำนาจใด (ข้อที่ 55)', '["นิติบัญญัติ, บริหาร, ตุลาการ","ประธานาธิบดี, รัฐสภา, ศาล","เทศบาล, อบจ., อบต.","ข้าราชการ, ทหาร, ตำรวจ"]', 0, 'อำนาจอธิปไตยแบ่งเป็น: นิติบัญญัติ (รัฐสภา), บริหาร (ครม.), ตุลาการ (ศาล)', 'อย่าสับสนกับการปกครองท้องถิ่น', 'อำนาจอธิปไตย = นิติบัญญัติ + บริหาร + ตุลาการ', '["หน้าที่พลเมืองและรัฐธรรมนูญ","Gifted"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_056', 'social', 'สังคมศึกษา', 'Regular', 2, 'ประวัติศาสตร์สมัยสุโขทัย', 'การปกครองสมัยสุโขทัยตอนต้นมีลักษณะเด่นตรงกับข้อใด (ข้อที่ 56)', '["การปกครองแบบปิตุราชา (พ่อปกครองลูก)","การปกครองแบบเทวราชา (สมมติเทพ)","การปกครองแบบธรรมราชา","การปกครองระบอบเทศาภิบาล"]', 0, 'สุโขทัยตอนต้นกษัตริย์ใกล้ชิดราษฎร มีการแขวนกระดิ่งร้องทุกข์', 'เทวราชาเริ่มรับอิทธิพลขอมในสมัยอยุธยา', 'สุโขทัยตอนต้น = แขวนกระดิ่ง = พ่อปกครองลูก', '["ประวัติศาสตร์สมัยสุโขทัย","Regular"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('so_057', 'social', 'สังคมศึกษา', 'Gifted', 3, 'เศรษฐศาสตร์: ระบบสหกรณ์', 'หลักการสำคัญที่สุดของระบบสหกรณ์ที่ต่างจากบริษัทเอกชนคือข้อใด (ข้อที่ 57)', '["สมาชิกทุกคนมีสิทธิออกเสียงคนละ 1 เสียงเท่ากัน ไม่ขึ้นกับจำนวนหุ้น","ผู้ถือหุ้นมากสุดมีสิทธิตัดสินใจ","รัฐบาลเป็นเจ้าของทั้งหมด","ห้ามจ่ายเงินปันผล"]', 0, 'สหกรณ์ยึดหลักประชาธิปไตย 1 คน 1 เสียง เท่าเทียมกัน', 'บริษัทจำกัดออกเสียงตามจำนวนหุ้น แต่สหกรณ์ 1 คน = 1 เสียง', 'สหกรณ์ = 1 คน 1 เสียง เท่าเทียมกัน', '["เศรษฐศาสตร์: ระบบสหกรณ์","Gifted"]');
